head.b:skin:
    /* ==================================================
       Design Parameters
       ================================================== */

    :root {

      /* --------------------------------------------------
         Colors
         -------------------------------------------------- */

      --color-page: #f1f1f1;
      --color-surface: #fcfcfc;
      --color-paper: #fcfcfc;

      --color-text: #202122;
      --color-muted: #54595d;

      --color-link: #0645ad;
      --color-link-hover: #0645ad;

      --color-border: #a2a9b1;
      --color-border-light: #c8ccd1;

      --color-code: #f8f9fa;
      --color-table-header: #eaecf0;
      --color-table-alt: #f8f9fa;

      --color-hover: #eaecf0;


      /* --------------------------------------------------
         Layout
         -------------------------------------------------- */

      --site-max-width: 1280px;
	  --search-max-width: 360px;

      --contents-width: 240px;

      --article-max-width: 900px;

      --layout-gap: 64px;

      --layout-padding-top: 72px;
      --layout-padding-right: 48px;
      --layout-padding-bottom: 72px;
      --layout-padding-left: 48px;

      /* --------------------------------------------------
         Base Typography
         -------------------------------------------------- */

      --base-font-size: 16px;
      --base-line-height: 1.6;

      --body-font-weight: 500;

      --body-font-family:
		"メイリオ",
        Meiryo,
		"ヒラギノ角ゴ Pro W3", Hiragino Kaku Gothic Pro, "ＭＳ Ｐゴシック",
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        "Noto Sans JP",
        "Hiragino Sans",
        "Yu Gothic",
        sans-serif;


      /* ==================================================
         ARTICLE PARAMETERS
         ================================================== */

      /* --------------------------------------------------
         Article Title
         -------------------------------------------------- */

      --article-title-size: 2.2rem;
      --article-title-weight: 700;
      --article-title-line-height: 1.3;

      --article-title-padding-bottom: 8px;

      --article-header-margin-bottom: 24px;


      /* --------------------------------------------------
         Article Body
         -------------------------------------------------- */

      --article-font-size: 1rem;
      --article-line-height: 1.5;

      --article-font-weight: 400;


	  /* --------------------------------------------------
         Article Meta
      　 -------------------------------------------------- */

      --article-meta-font-size: 1rem;
      --article-meta-line-height: 1.6;
      --article-meta-color: #54595d;
      --article-meta-border: #c8ccd1;
      --article-meta-gap: 12px;


	  /* --------------------------------------------------
         Article Image
      　 -------------------------------------------------- */

	  --article-image-max-width: 533px;
      --article-image-max-height: 300px;
      --article-image-margin-top: 1.5em;
      --article-image-margin-bottom: 1.5em;
      --article-image-caption-size: 0.85rem;
      --article-image-caption-color: #54595d;


	  /* --------------------------------------------------
         Article Image
      　 -------------------------------------------------- */

	  --article-video-max-width: 533px;
      --article-video-max-height: 300px;


	  /* --------------------------------------------------
         Auto Gallery
      　 -------------------------------------------------- */

      --gallery-gap: 12px;
      --gallery-item-width: 210px;
      --gallery-image-height: 160px;
      --gallery-margin-top: 40px;
      --gallery-margin-bottom: 40px;


      /* --------------------------------------------------
         H2
         -------------------------------------------------- */

      --h2-size: 1.55rem;
      --h2-weight: 600;
      --h2-line-height: 1.4;

      --h2-margin-top: 2.2em;
      --h2-margin-bottom: 0.8em;

      --h2-padding-bottom: 5px;


      /* --------------------------------------------------
         H3
         -------------------------------------------------- */

      --h3-size: 1.2rem;
      --h3-weight: 700;
      --h3-line-height: 1.4;

      --h3-margin-top: 1.8em;
      --h3-margin-bottom: 0.6em;


      /* --------------------------------------------------
         Paragraph
         -------------------------------------------------- */

      --paragraph-margin-bottom: 1em;


      /* --------------------------------------------------
         Lists
         -------------------------------------------------- */

      --list-margin-top: 0.5em;
      --list-margin-bottom: 1.2em;


      /* --------------------------------------------------
         Contents
         -------------------------------------------------- */

      --contents-font-size: 0.88rem;

      --contents-title-size: 0.95rem;
      --contents-title-weight: 600;

      --contents-title-margin-bottom: 10px;
      --contents-title-padding-bottom: 6px;

      --contents-item-margin: 2px 0;

      --contents-link-padding: 2px 4px;

      --contents-sublevel-indent: 16px;

      --contents-sticky-top: 20px;

	  --contents-label-weight: 500;


      /* ==================================================
         INDEX / HOME PARAMETERS
         ================================================== */

      /* --------------------------------------------------
         Home
         -------------------------------------------------- */

      --home-max-width: 900px;

      --home-introduction-margin-bottom: 40px;

      --home-heading-size: 1.55rem;
      --home-heading-weight: 600;
      --home-heading-line-height: 1.4;

      --home-heading-margin-bottom: 16px;
      --home-heading-padding-bottom: 5px;

      --home-text-line-height: 1.85;

	  --home-sidebar-section-gap: 32px;

      --article-list-item-margin-bottom: 20px;
      --article-list-item-padding-bottom: 14px;

      --article-list-item-gap: 20px;
      --article-list-item-margin-bottom: 14px;
      --article-list-item-padding-bottom: 10px;

      --article-list-meta-size: 0.75rem;
      --article-list-meta-margin-bottom: 5px;

      --article-list-title-size: 1.1rem;
      --article-list-title-margin-bottom: 5px;
      --article-list-title-line-height: 1.4;
	  --article-list-title-weight: 600;

      --article-list-abstract-size: 0.88rem;
      --article-list-abstract-line-height: 1.55;

      --article-list-thumbnail-width: 240px;
      --article-list-thumbnail-max-height: 150px;

	  --article-list-mobile-thumbnail-max-height: 220px;


	/* --------------------------------------------------
         Popular-post
       -------------------------------------------------- */

      --popular-post-item-gap: 10px;
      --popular-post-item-margin-bottom: 10px;

      --popular-post-title-size: 0.9rem;
      --popular-post-title-line-height: 1.4;
	　--popular-post-title-weight: 600;

      --popular-post-abstract-size: 0.78rem;
      --popular-post-abstract-line-height: 1.45;

      --popular-post-thumbnail-width: 72px;
      --popular-post-thumbnail-height: 54px;

      --popular-post-meta-size: 0.72rem;



      /* ==================================================
         COMPONENT PARAMETERS
         ================================================== */

      /* --------------------------------------------------
         Blockquote
         -------------------------------------------------- */

      --blockquote-margin-top: 1.5em;
      --blockquote-margin-bottom: 1.5em;

      --blockquote-padding-top: 10px;
      --blockquote-padding-right: 16px;
      --blockquote-padding-bottom: 10px;
      --blockquote-padding-left: 16px;

      --blockquote-border-width: 4px;

      --blockquote-font-color: #54595d;


      /* --------------------------------------------------
         Inline Code
         -------------------------------------------------- */

      --inline-code-padding-vertical: 2px;
      --inline-code-padding-horizontal: 4px;

      --inline-code-size: 0.9em;


      /* --------------------------------------------------
         Code Block
         -------------------------------------------------- */

      --code-font-size: 0.88rem;
      --code-line-height: 1.65;

      --code-padding-top: 14px;
      --code-padding-right: 16px;
      --code-padding-bottom: 14px;
      --code-padding-left: 16px;

      --code-margin-top: 0.5em;
      --code-margin-bottom: 1.5em;

      --code-tab-size: 4;


      /* --------------------------------------------------
         Prism Toolbar
         -------------------------------------------------- */

      --toolbar-button-size: 0.8rem;

      --toolbar-button-padding-vertical: 5px;
      --toolbar-button-padding-horizontal: 9px;


      /* --------------------------------------------------
         Notice
         -------------------------------------------------- */

      --notice-margin-top: 1.5em;
      --notice-margin-bottom: 1.5em;

      --notice-padding-top: 12px;
      --notice-padding-right: 16px;
      --notice-padding-bottom: 12px;
      --notice-padding-left: 16px;

      --notice-border-left-width: 4px;


      /* --------------------------------------------------
         Table
         -------------------------------------------------- */

      --table-font-size: 0.92rem;

      --table-cell-padding-vertical: 7px;
      --table-cell-padding-horizontal: 10px;


      /* --------------------------------------------------
         Infobox
         -------------------------------------------------- */

      --infobox-width: 280px;

      --infobox-margin-bottom: 20px;
      --infobox-margin-left: 24px;

      --infobox-font-size: 0.88rem;


      /* --------------------------------------------------
         Footer
         -------------------------------------------------- */

      --footer-margin-top: 60px;
      --footer-font-size: 0.8rem;

      --footer-padding-top: 24px;
      --footer-padding-right: 24px;
      --footer-padding-bottom: 24px;
      --footer-padding-left: 24px;


      /* --------------------------------------------------
         Responsive
         -------------------------------------------------- */

      --breakpoint-mobile: 800px;

      --mobile-layout-padding: 16px;

      --mobile-article-title-size: 1.8rem;

      --mobile-code-font-size: 0.82rem;

      --mobile-code-padding: 12px;

      --mobile-contents-margin-bottom: 24px;
      --mobile-contents-padding: 12px;

      --mobile-infobox-margin-bottom: 20px;
    }


    /* ==================================================
       BASE
       ================================================== */

    * {
      box-sizing: border-box;
    }

    html {
      font-size: var(--base-font-size);
    }

    body {
      margin: 0;

      background: var(--color-page);
      color: var(--color-text);

      font-family: var(--body-font-family);

      font-size: var(--base-font-size);
      font-weight: var(--body-font-weight);
      line-height: var(--base-line-height);
    }

    a {
      color: var(--color-link);
      text-decoration: none;
    }

    a:hover {
      color: var(--color-link-hover);
      text-decoration: underline;
    }




    /* ==================================================
       MAIN LAYOUT
       ================================================== */

    .site-layout {
      max-width: var(--site-max-width);
      margin: 0 auto;
      display: grid;
      grid-template-columns: var(--contents-width) minmax(0, 1fr);
      gap: var(--layout-gap);
      padding:
        var(--layout-padding-top)
        var(--layout-padding-right)
        var(--layout-padding-bottom)
        var(--layout-padding-left);
      background: var(--color-surface);

      min-height: calc(100vh - 180px);
    }

    /* ==================================================
       CONTENTS
       ================================================== */

    .contents {
      position: sticky;
      top: var(--contents-sticky-top);
      max-height: calc(100vh - 60px);
      align-self: start;
      font-size: var(--contents-font-size);
      overflow-y: auto;
    }

    .contents-title {
      margin: 0 0 var(--contents-title-margin-bottom);

      font-size: var(--contents-title-size);
      font-weight: var(--contents-title-weight);

      border-bottom: 1px solid var(--color-border-light);

      padding-bottom: var(--contents-title-padding-bottom);
    }

    .contents ul {
      list-style: none;
      margin: 0;
      padding: 0;
    }

    .contents li {
      margin: var(--contents-item-margin);
    }

    .contents li a {
      display: block;

      padding:
        var(--contents-link-padding);

      color: var(--color-link);

      font-weight: var(--contents-label-weight);
    }

    .contents li a:hover {
      background: var(--color-hover);
      text-decoration: none;
    }

    .contents .level-2 {
      padding-left: var(--contents-sublevel-indent);
    }

	.contents-top-link {
	  color: var(--color-link);
	  font-weight: var(--contents-label-weight);
	}


    /* ==================================================
       ARTICLE
       Article-related styles start here.
       ================================================== */


    /* --------------------------------------------------
       Article Layout
       -------------------------------------------------- */

    .article-main {
      min-width: 0;
      max-width: var(--article-max-width);

      background: var(--color-paper);
    }


    /* --------------------------------------------------
       Article Header
       -------------------------------------------------- */

    .article-header {
      margin-bottom: var(--article-header-margin-bottom);
    }

    .article-title {
      margin: 0;

      font-size: var(--article-title-size);
      font-weight: var(--article-title-weight);
      line-height: var(--article-title-line-height);

      border-bottom: 1px solid var(--color-border);

      padding-bottom: var(--article-title-padding-bottom);
    }

    .article-lead {
      margin-top: 16px;
      font-size: var(--article-font-size);
    }


    /* --------------------------------------------------
       Article Meta
       -------------------------------------------------- */

    .article-meta {
      display: flex;
      flex-wrap: wrap;
      gap: var(--article-meta-gap);

      margin-top: 12px;

      color: var(--article-meta-color);
      font-size: var(--article-meta-font-size);
      line-height: var(--article-meta-line-height);
    }

    .article-meta-item {
      display: inline;
    }

    .article-meta-label {
      font-weight: 600;
    }

    .article-meta a {
      color: var(--color-link);
    }

    .article-meta a:hover {
      text-decoration: underline;
    }


    /* --------------------------------------------------
       Article Body
       -------------------------------------------------- */

    .article-body {
      font-family: var(--body-font-family);

      font-size: var(--article-font-size);
      font-weight: var(--article-font-weight);
      line-height: var(--article-line-height);
    }


    /* --------------------------------------------------
       Headings
       -------------------------------------------------- */

    .article-body h2 {
      margin-top: var(--h2-margin-top);
      margin-bottom: var(--h2-margin-bottom);

      padding-bottom: var(--h2-padding-bottom);

      border-bottom: 1px solid var(--color-border);

      font-size: var(--h2-size);
      font-weight: var(--h2-weight);
      line-height: var(--h2-line-height);
    }

    .article-body h3 {
      margin-top: var(--h3-margin-top);
      margin-bottom: var(--h3-margin-bottom);

      border-bottom: 0;

      font-size: var(--h3-size);
      font-weight: var(--h3-weight);
      line-height: var(--h3-line-height);
    }


    /* --------------------------------------------------
       Paragraphs
       -------------------------------------------------- */

    .article-body p {
      margin: 0 0 var(--paragraph-margin-bottom);
    }


    /* --------------------------------------------------
       Lists
       -------------------------------------------------- */

    .article-body ul,
    .article-body ol {
      margin-top: var(--list-margin-top);
      margin-bottom: var(--list-margin-bottom);
    }


    /* --------------------------------------------------
       Blockquote
       -------------------------------------------------- */

    .article-body blockquote {
      margin:
        var(--blockquote-margin-top)
        0
        var(--blockquote-margin-bottom);

      padding:
        var(--blockquote-padding-top)
        var(--blockquote-padding-right)
        var(--blockquote-padding-bottom)
        var(--blockquote-padding-left);

      border-left:
        var(--blockquote-border-width)
        solid
        var(--color-border);

      background: var(--color-code);

      color: var(--blockquote-font-color);
    }


    /* --------------------------------------------------
       Images
       -------------------------------------------------- */

    .article-image {
      margin: var(--article-image-margin-top) 0 var(--article-image-margin-bottom);
      text-align: center;
    }

    .article-image img {
      display: block;
      width: auto !important;
      height: auto !important;
      max-width: 100% !important;
      max-height: var(--article-image-max-height) !important;
      margin: 0 auto;
      object-fit: contain;
      cursor: zoom-in;
    }

    .article-image-caption {
      margin-top: 6px;
      color: var(--article-image-caption-color);
      font-size: var(--article-image-caption-size);
      line-height: 1.5;
      text-align: left;
    }


    /* --------------------------------------------------
       Image Modal
       -------------------------------------------------- */

    .image-modal {
      position: fixed;
      inset: 0;
      z-index: 9999;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      background: rgba(0, 0, 0, 0.85);
      cursor: zoom-out;
    }

    .image-modal img {
      display: block;
      max-width: 95vw;
      max-height: 90vh;
      width: auto;
      height: auto;
      object-fit: contain;
    }

    .image-modal-caption {
      position: absolute;
      left: 50%;
      bottom: 24px;
      transform: translateX(-50%) translateY(8px);
      max-width: min(720px, calc(100vw - 48px));
      padding: 8px 14px;
      border-radius: 4px;
      background: rgba(0, 0, 0, 0.72);
      color: #fff;
      font-size: 0.85rem;
      line-height: 1.5;
      text-align: center;
      pointer-events: none;

      opacity: 0;
      transition:
        opacity 0.2s ease,
        transform 0.2s ease;
    }

    .image-modal:has(img:hover) .image-modal-caption {
      opacity: 1;
      transform: translateX(-50%) translateY(0);
    }

    .image-modal-close {
      position: absolute;
      top: 12px;
      right: 18px;
      border: 0;
      background: transparent;
      color: #fff;
      font-size: 2rem;
      line-height: 1;
      cursor: pointer;
    }


    /* --------------------------------------------------
       Auto Gallery
       -------------------------------------------------- */

    .article-gallery {
      position: relative;
      margin: var(--gallery-margin-top) 0 var(--gallery-margin-bottom);
    }

    .article-gallery-title {
      margin-bottom: 12px;
      border-bottom: 1px solid var(--color-border);
    }

    .article-gallery-viewport {
      position: relative;
      overflow: hidden;
    }

    .article-gallery-track {
      display: flex;
      gap: var(--gallery-gap);

      overflow-x: auto;
      scroll-behavior: smooth;

      scrollbar-width: none;
      cursor: grab;

      user-select: none;
      -webkit-overflow-scrolling: touch;
    }

    .article-gallery-track::-webkit-scrollbar {
      display: none;
    }

    .article-gallery-track.is-dragging {
      cursor: grabbing;
      scroll-behavior: auto;
    }

    .article-gallery-item {
      flex: 0 0 var(--gallery-item-width);
      margin: 0;
      cursor: zoom-in;
    }

    .article-gallery-item img {
      display: block;
      width: 100%;
      height: var(--gallery-image-height);
      object-fit: cover;
    }

    .article-gallery-item figcaption {
      margin-top: 5px;
      color: var(--color-muted);
      font-size: 0.8rem;
      line-height: 1.4;
    }


    /* --------------------------------------------------
       Gallery Navigation
       -------------------------------------------------- */

    .article-gallery-prev,
    .article-gallery-next {
      position: absolute;
      top: 50%;
      z-index: 2;

      width: 38px;
      height: 52px;

      transform: translateY(-50%);

      border: 0;
      border-radius: 3px;

      background: rgba(0, 0, 0, 0.55);
      color: #fff;

      font-size: 1.8rem;
      line-height: 1;

      cursor: pointer;
    }

    .article-gallery-prev {
      left: 6px;
    }

    .article-gallery-next {
      right: 6px;
    }

    .article-gallery-prev:hover,
    .article-gallery-next:hover {
      background: rgba(0, 0, 0, 0.75);
    }

    .article-gallery-prev:disabled,
    .article-gallery-next:disabled {
      opacity: 0.25;
      cursor: default;
    }


    /* --------------------------------------------------
       Article References
       Reference Engine
       -------------------------------------------------- */

    /*
     * 参考文献
     * 脚注
     * 図
     * 表
     * 数式
     * コード
     *
     * 共通Reference Engine用
     */


    /* ------------------------------
       References
       ------------------------------ */

    .article-references {
    }

    .article-reference-section-title {
      margin: 0 0 16px;
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--color-text);
    }


    /*
     * 文献・脚注
     *
     * 個別の横線は入れない。
     */

    .article-references .article-target {
      margin: 10px 0;
      line-height: 1.7;
    }


    /* ------------------------------
       Target
       ------------------------------ */

    .article-target {
      position: relative;
    }


    /*
     * Targetの番号
     *
     * 図1
     * 表1
     * 式(1)
     * コード例1
     * [1]
     * など
     */

    .article-target-number {
      display: inline-block;
      margin-right: 6px;
    }


    /* ------------------------------
       Reference Link
       ------------------------------ */

    /*
     * 基本は通常の本文位置。
     *
     * 図・表・数式・コードは
     * この状態で表示される。
     */

    .article-ref-link {
      position: relative;
      color: var(--color-link);
      text-decoration: none;
    }


    /*
     * Reference / Footnoteのみ上付き
     */

    .article-ref-link.is-superscript {
      vertical-align: super;
      font-size: 0.75em;
      line-height: 0;
    }

    .article-ref-link:hover {
      text-decoration: underline;
    }


    /* ------------------------------
       Reference Hover Preview
       ------------------------------ */

    .article-ref-preview,
    .article-reference-preview {
      position: absolute;

      left: 50%;
      top: calc(100% + 10px);

      z-index: 1000;

      width: 300px;
      padding: 10px 12px;

      transform: translateX(-50%);

      background: #fff;
      border: 1px solid var(--color-border);
      border-radius: 4px;

      color: var(--color-text);
      font-size: 0.85rem;
      line-height: 1.5;

      box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12);

      opacity: 0;
      visibility: hidden;
      pointer-events: none;

      transition:
        opacity 0.15s ease,
        visibility 0.15s ease;
    }


    /*
     * 本文側
     * Target側
     *
     * どちらもホバーでプレビュー表示
     */

    .article-ref-link:hover .article-ref-preview,
    .article-reference-back:hover .article-reference-preview {
      opacity: 1;
      visibility: visible;
    }


    /*
     * コードはプレビューなし
     */

    .article-ref-link[data-preview="off"] .article-ref-preview {
      display: none;
    }


    /* ------------------------------
       Target → 本文
       ------------------------------ */

    .article-reference-back {
      position: relative;

      margin-left: 8px;

      color: var(--color-link);
      text-decoration: none;

      font-size: 0.85em;
    }

    .article-reference-back:hover {
      text-decoration: underline;
    }


    /* ------------------------------
       Figure
       ------------------------------ */

    /*
     * 図のタイトル・説明は
     * 図の下に配置する。
     */

    .article-figure {
      margin: 0;
    }

    .article-figure figcaption {
      margin-top: 8px;

      color: var(--color-muted);
      font-size: 0.85rem;
      line-height: 1.5;
      text-align: left;
    }

    .article-figure .article-target-number {
      margin-right: 6px;
    }


    /* ------------------------------
       Table
       ------------------------------ */

    /*
     * 表タイトルは
     * 表の上に配置する。
     */

    .article-table-title {
      margin-bottom: 3px;

      font-weight: 600;
      line-height: 1.5;
    }

    .article-table-title .article-target-number {
      margin-right: 6px;
    }


    /* ------------------------------
       Legacy compatibility
       ------------------------------ */

    .article-reference {
      margin: 8px 0;
      line-height: 1.7;
    }

    .article-reference-number {
      margin-right: 6px;
      color: var(--color-link);
      text-decoration: none;
    }

    .article-reference-number:hover {
      text-decoration: underline;
    }


    /* ------------------------------
       Equation
       ------------------------------ */

    .article-equation {
      position: relative;

      display: flex;
      align-items: center;
      justify-content: center;

      width: 100%;
    }

    .article-equation .equation-content {
      flex: 1;
      text-align: center;
    }

    .article-equation .article-target-number {
      position: absolute;
      right: 0;

      margin: 0;
    }

    .equation-content {
      display: inline-block;
    }


    /* ------------------------------
       Code Target
       ------------------------------ */

    /*
     * Reference Engineの番号が
     * コードブロックの直前に表示されるため、
     * 少し余白を確保する。
     */

    .article-target[data-type="code"] {
      margin-top: 24px;
      margin-bottom: 24px;
    }


    /* ------------------------------
       Table Target
       ------------------------------ */

    .article-target[data-type="table"] {
      margin-top: 24px;
      margin-bottom: 24px;
    }


    /* ------------------------------
       Figure Target
       ------------------------------ */

    .article-target[data-type="fig"] {
      margin-top: 24px;
      margin-bottom: 24px;
    }


    /* ------------------------------
       Footnote Target
       ------------------------------ */

    .article-footnotes .article-target {
      margin: 8px 0;
      line-height: 1.7;
    }


    /* --------------------------------------------------
       Inline Code
       -------------------------------------------------- */

    .article-body p code,
    .article-body li code,
    .article-body td code,
    .article-body h1 code,
    .article-body h2 code,
    .article-body h3 code,
    .article-body h4 code {
      padding:
        var(--inline-code-padding-vertical)
        var(--inline-code-padding-horizontal);

      background: var(--color-code);

      border: 1px solid var(--color-border-light);

      font-family:
        "SFMono-Regular",
        "Cascadia Code",
        "Roboto Mono",
        Consolas,
        "Liberation Mono",
        monospace;

      font-size: var(--inline-code-size);
    }


    /* --------------------------------------------------
       Code Block
       -------------------------------------------------- */

    .article-body pre[class*="language-"] {
      position: relative;

      margin:
        var(--code-margin-top)
        0
        var(--code-margin-bottom);

      padding:
        var(--code-padding-top)
        var(--code-padding-right)
        var(--code-padding-bottom)
        var(--code-padding-left);

      background: var(--color-code) !important;

      border: 0 !important;
      border-radius: 0 !important;
      box-shadow: none !important;

      overflow-x: auto;
      overflow-y: hidden;

      white-space: pre;

      -webkit-overflow-scrolling: touch;
      scrollbar-width: thin;
    }

    .article-body pre[class*="language-"] > code {
      display: block;

      padding: 0 !important;
      margin: 0;

      background: transparent !important;

      border: 0 !important;
      border-radius: 0 !important;
      box-shadow: none !important;

      font-family:
        "SFMono-Regular",
        "Cascadia Code",
        "Roboto Mono",
        Consolas,
        "Liberation Mono",
        monospace;

      font-size: var(--code-font-size);
      line-height: var(--code-line-height);

      white-space: pre;

      word-break: normal;
      overflow-wrap: normal;

      tab-size: var(--code-tab-size);
    }


    /* --------------------------------------------------
       Prism Toolbar
       -------------------------------------------------- */

    .article-body .toolbar {
      opacity: 1;
    }

    .article-body .toolbar .toolbar-item button {
      padding:
        var(--toolbar-button-padding-vertical)
        var(--toolbar-button-padding-horizontal);

      border: 0;

      background: transparent;

      color: #72777d;

      font-family: inherit;
      font-size: var(--toolbar-button-size);

      cursor: pointer;
    }

    .article-body .toolbar .toolbar-item button:hover {
      background: var(--color-hover);
      color: var(--color-text);
    }


    /* --------------------------------------------------
       Notice
       -------------------------------------------------- */

    .notice {
      margin:
        var(--notice-margin-top)
        0
        var(--notice-margin-bottom);

      padding:
        var(--notice-padding-top)
        var(--notice-padding-right)
        var(--notice-padding-bottom)
        var(--notice-padding-left);

      border: 1px solid var(--color-border);

      border-left:
        var(--notice-border-left-width)
        solid
        #3366cc;

      background: var(--color-code);
    }

    .notice p {
      margin: 5px 0 0;
    }


    /* --------------------------------------------------
       Wikipedia-like Table
       -------------------------------------------------- */

    .wikitable {
      margin: 0.5em 0;

      border-collapse: collapse;

      background: var(--color-page);

      font-size: var(--table-font-size);
    }

    .wikitable th,
    .wikitable td {
      border: 1px solid var(--color-border);

      padding:
        var(--table-cell-padding-vertical)
        var(--table-cell-padding-horizontal);

      text-align: left;
      vertical-align: top;
    }

    .wikitable th {
      background: var(--color-table-header);
      font-weight: 600;
    }

    .wikitable tr:nth-child(even) {
      background: var(--color-table-alt);
    }


    /* --------------------------------------------------
       Infobox
       -------------------------------------------------- */

    .infobox {
      float: right;

      width: var(--infobox-width);

      margin:
        0
        0
        var(--infobox-margin-bottom)
        var(--infobox-margin-left);

      border: 1px solid var(--color-border);

      background: var(--color-code);

      font-size: var(--infobox-font-size);
    }

    .infobox-title {
      padding: 8px;

      background: var(--color-table-header);

      text-align: center;
      font-weight: 600;
    }

    .infobox table {
      width: 100%;
      border-collapse: collapse;
    }

    .infobox th,
    .infobox td {
      padding: 6px 8px;

      border-top: 1px solid var(--color-border-light);

      vertical-align: top;
    }

    .infobox th {
      width: 35%;
      font-weight: 600;
    }


    /* --------------------------------------------------
       Article Comments
       -------------------------------------------------- */

    .article-comments {
      margin-top: 40px;
      padding-top: 24px;
      border-top: 1px solid var(--color-border);
    }

    .article-comments-title {
      margin-bottom: 20px;
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--color-text);
    }


    /* ==================================================
       ARTICLE REFERENCE CARD
       ================================================== */

    .article-ref-card {
      margin: 24px 0;
      padding: 0;

      background: #fcfcfc;
      border: 1px solid #c8ccd1;

      box-sizing: border-box;
    }

    /* =========================
       記事番号ヘッダー
       ========================= */

    .article-ref-header {
      padding: 8px 16px;

      background: #eaecf0;
      border-bottom: 1px solid #c8ccd1;

      color: #202122;
      font-size: 0.85rem;
      font-weight: 600;
      line-height: 1.4;
    }

    /* =========================
       カードボディ
       ========================= */

    .article-ref-body {
      display: grid;
      grid-template-columns: 180px minmax(0, 1fr);
      column-gap: 20px;

      padding: 16px;

      box-sizing: border-box;
    }

    /* =========================
       画像
       ========================= */

    .article-ref-image-link {
      display: block;
      grid-column: 1;
    }

    .article-ref-image {
      display: block;

      width: 180px;
      height: 120px;

      object-fit: cover;
    }

    /* =========================
       情報エリア
       ========================= */

    .article-ref-info {
      grid-column: 2;
      min-width: 0;
    }

    /* =========================
       タイトル
       ========================= */

    .article-ref-title {
      display: block;

      color: var(--color-link);
      font-size: 1rem;
      font-weight: 600;
      line-height: 1.4;

      text-decoration: none;
    }

    .article-ref-title:hover {
      text-decoration: underline;
    }

    /* =========================
       メタデータ
       ========================= */

    .article-ref-meta {
      margin-top: 6px;

      color: var(--color-muted);
      font-size: 0.8rem;
      line-height: 1.5;
    }

    /* =========================
       Abstract
       ========================= */

    .article-ref-abstract {
      margin-top: 8px;

      color: var(--color-text);
      font-size: 0.85rem;
      line-height: 1.55;
    }

    /* ============================================================
       YouTube動画
       ============================================================ */

        .article-video {
      width: 100%;
      max-width: var(--article-video-max-width);
      margin: 24px auto 0;
    }

    .article-video iframe {
      display: block;
      width: 100%;
      aspect-ratio: 16 / 9;
      max-height: var(--article-video-max-height);
      height: auto;
      border: 0;
    }

    .article-video-title {
      max-width: 900px;
      margin: 8px auto 24px;
      color: var(--color-text);
      font-size: 0.85rem;
      line-height: 1.5;
      text-align: center;
    }

    /* ==================================================
       INDEX / HOME
       ================================================== */

    /* --------------------------------------------------
       Home Layout
       -------------------------------------------------- */

    .article-main:has(.home-main) {
      max-width: none;
      width: 100%;
    }

    .home-main {
      max-width: none;
      width: 100%;
    }

    .home-introduction {
      margin-bottom: var(--home-introduction-margin-bottom);
    }

    .home-introduction-inner {
      max-width: 760px;
      padding: 0 0 8px;
    }

    .home-site-name {
      margin-bottom: 10px;
      color: var(--color-text);
      font-size: 1.15rem;
      font-weight: 600;
      line-height: 1.4;
    }

    .home-introduction p {
      margin: 0;
      color: var(--color-muted);
      font-size: 0.9rem;
      line-height: 1.8;
    }

    .home-introduction h2,
    .article-list h2 {
      margin-top: 0;
      margin-bottom: var(--home-heading-margin-bottom);
      padding-bottom: var(--home-heading-padding-bottom);
      border-bottom: 1px solid var(--color-border);
      font-size: var(--home-heading-size);
      font-weight: var(--home-heading-weight);
      line-height: var(--home-heading-line-height);
    }

    .site-layout.home-layout {
      grid-template-columns: minmax(0, 1fr) 320px;
    }


    /* --------------------------------------------------
       Home Sidebar
       -------------------------------------------------- */

    .home-sidebar {
      min-width: 0;
    }

    .home-sidebar-section h2 {
      margin-top: 0;
      margin-bottom: var(--home-heading-margin-bottom);
      padding-bottom: var(--home-heading-padding-bottom);
      border-bottom: 1px solid var(--color-border);
      color: var(--color-text);
      font-size: var(--home-heading-size);
      font-weight: var(--home-heading-weight);
      line-height: var(--home-heading-line-height);
    }

    .home-sidebar-section > .widget + .widget h2 {
      margin-top: var(--home-sidebar-section-gap);
    }

    /* --------------------------------------------------
       Home Sidebar Lists
       -------------------------------------------------- */

    .home-sidebar ul {
      list-style: none;
      margin: 0;
      padding: 0 0 0 8px;
    }

    .home-sidebar li {
      list-style: none;
    }


    /* --------------------------------------------------
       Popular Posts
       -------------------------------------------------- */

    .home-sidebar .popular-posts ul {
      margin: 0;
      padding: 0;
    }

    .home-sidebar .popular-posts li {
      position: relative;

      display: block;

      margin: 0 0 var(--popular-post-item-margin-bottom);
      padding: 0 0 var(--popular-post-item-margin-bottom);

      border-bottom: 1px solid var(--color-border);
    }

    .home-sidebar .popular-posts li:last-child {
      margin-bottom: 0;
      padding-bottom: 0;
      border-bottom: 0;
    }


    /* --------------------------------------------------
       Popular Posts Title
       -------------------------------------------------- */

    .home-sidebar .popular-posts .item-title {
      margin: 0;
      font-size: var(--popular-post-title-size);
      line-height: var(--popular-post-title-line-height);
    }

    .home-sidebar .popular-posts .item-title a {
      color: var(--color-link);
      text-decoration: none;
	  font-weight: var(--popular-post-title-weight);
    }


    /* --------------------------------------------------
       Popular Posts Abstract / Snippet
       -------------------------------------------------- */

    .home-sidebar .popular-post-abstract,
    .home-sidebar .popular-posts .item-snippet {
      margin-top: 4px;
      color: var(--color-text);
      font-size: var(--popular-post-abstract-size);
      line-height: var(--popular-post-abstract-line-height);
    }


    /* --------------------------------------------------
       Popular Posts Thumbnail
       -------------------------------------------------- */

    .home-sidebar .popular-posts .item-thumbnail {
      float: right;
      width: var(--popular-post-thumbnail-width);
      margin: 0 0 4px var(--popular-post-item-gap);
    }

    .home-sidebar .popular-posts .item-thumbnail img {
      display: block;
      width: 100%;
      height: var(--popular-post-thumbnail-height);
      object-fit: cover;
    }


    /* --------------------------------------------------
       Home Category List
       -------------------------------------------------- */

    .home-category-list {
      display: flex;
      flex-direction: column;
      gap: 0;
    }

    .home-category-list a {
      display: block;
      padding: 4px 0;
      border: 0;
      color: var(--color-link);
      font-size: 0.9rem;
      line-height: 1.5;
    }

    .home-category-name {
      display: inline;
    }

    .home-category-count {
      display: inline;
      margin-left: 6px;
      color: var(--color-muted);
      font-size: 0.8rem;
      white-space: nowrap;
    }


    /* --------------------------------------------------
       Article List
       -------------------------------------------------- */

    .article-list-item {
      display: grid;
      grid-template-columns: minmax(0, 1fr) var(--article-list-thumbnail-width);
      gap: var(--article-list-item-gap);
      align-items: start;

      margin-bottom: var(--article-list-item-margin-bottom);
      padding-bottom: var(--article-list-item-padding-bottom);

      border-bottom: 1px solid var(--color-border);
    }

    .article-list-content {
      min-width: 0;
    }


    /* --------------------------------------------------
       Article List Meta
       -------------------------------------------------- */

    .article-list-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 4px 12px;

      margin-bottom: var(--article-list-meta-margin-bottom);

      color: var(--color-muted);
      font-size: var(--article-list-meta-size);
      line-height: 1.4;
    }

    .article-list-meta a {
      color: var(--color-link);
    }


    /* --------------------------------------------------
       Article List Title
       -------------------------------------------------- */

    .article-list-item h3 {
      margin: 0 0 var(--article-list-title-margin-bottom);

      font-size: var(--article-list-title-size);
      font-weight: var(--article-list-title-weight);
      line-height: var(--article-list-title-line-height);
    }

    .article-list-item h3 a {
      color: var(--color-link);
    }


    /* --------------------------------------------------
       Article List Abstract
       -------------------------------------------------- */

    .article-list-abstract {
      margin: 0;
      color: var(--color-text);
      font-size: var(--article-list-abstract-size);
      line-height: var(--article-list-abstract-line-height);
    }


    /* --------------------------------------------------
       Article List Thumbnail
       -------------------------------------------------- */

    .article-list-thumbnail-container {
      min-width: 0;

      display: flex;
      justify-content: center;
      align-items: center;
    }

    .article-list-thumbnail {
      width: 100%;

      display: flex;
      justify-content: center;
      align-items: center;
    }

    .article-list-thumbnail img {
      display: block;

      width: auto;
      height: auto;

      max-width: 100%;
      max-height: var(--article-list-thumbnail-max-height);

      object-fit: contain;
    }


    /* --------------------------------------------------
       Article List Source
       -------------------------------------------------- */

    .index-article-source {
      display: none;
    }


    /* --------------------------------------------------
       Article List Navigation
       -------------------------------------------------- */

    .article-list-more,
    .blog-pager {
      display: flex;
      justify-content: center;
      gap: 12px;
      margin-top: 28px;
    }

    .article-list-more-link,
    .blog-pager a {
      display: inline-block;

      padding: 8px 24px;

      border: 1px solid var(--color-border);

      background: var(--color-surface);
      color: var(--color-link);

      font-size: 0.9rem;
      line-height: 1.5;
      text-decoration: none;
    }

    .article-list-more-link:hover,
    .blog-pager a:hover {
      background: var(--color-hover);
    }

    /* --------------------------------------------------
       Featured Post
       -------------------------------------------------- */

    #FeaturedPost1 {
      margin: 0 0 48px;
      padding: 28px 32px 32px;

      border: 1px solid var(--color-border);

      background: #f5f6f6;
    }


    /* --------------------------------------------------
       Featured Post Heading
       -------------------------------------------------- */

    #FeaturedPost1 > .title {
      margin: 0 0 24px;
      padding: 0 0 8px;

      border-bottom: 2px solid var(--color-text);

      color: var(--color-text);

      font-size: 1.55rem;
      font-weight: 600;
      line-height: 1.4;
    }


    /* --------------------------------------------------
       Featured Post Body
       -------------------------------------------------- */

    #FeaturedPost1 .post-summary {
      display: grid;

      grid-template-columns:
        minmax(0, 1fr)
        320px;

      grid-template-areas:
        "title image"
        "abstract image"
        "more image";

      gap: 0 32px;

      align-items: start;
    }


    /* --------------------------------------------------
       Featured Post Title
       -------------------------------------------------- */

    #FeaturedPost1 .post-summary h3 {
      grid-area: title;

      margin: 0 0 18px;

      font-size: 1.55rem;
      font-weight: 600;
      line-height: 1.45;
    }

    #FeaturedPost1 .post-summary h3 a {
      color: var(--color-link);
      text-decoration: none;
    }

    #FeaturedPost1 .post-summary h3 a:hover {
      text-decoration: underline;
    }


    /* --------------------------------------------------
       Featured Post Abstract
       -------------------------------------------------- */

    #FeaturedPost1 .featured-post-abstract {
      grid-area: abstract;

      margin: 0;

      color: var(--color-text);

      font-size: 0.95rem;
      line-height: 1.85;
    }


    /* --------------------------------------------------
       Featured Post Image
       -------------------------------------------------- */

    #FeaturedPost1 .post-summary .image {
      grid-area: image;

      display: block;

      width: 100%;
      height: 220px;

      object-fit: cover;
    }

    /* --------------------------------------------------
       Featured Post without Image
       -------------------------------------------------- */

    #FeaturedPost1.featured-post-no-image .post-summary {
      grid-template-columns: 1fr;

      grid-template-areas:
        "title"
        "abstract"
        "more";
    }

    #FeaturedPost1.featured-post-no-image .post-summary h3 {
      max-width: 820px;
    }

    #FeaturedPost1.featured-post-no-image .featured-post-abstract {
      max-width: 820px;
    }


    /* --------------------------------------------------
       Featured Post Read More
       -------------------------------------------------- */

    #FeaturedPost1 .featured-post-more {
      grid-area: more;

      display: inline-block;

      width: fit-content;

      margin-top: 24px;
      padding: 6px 14px;

      border: 1px solid var(--color-border);

      color: var(--color-link);

      font-size: 0.82rem;
      line-height: 1.5;

      text-decoration: none;
    }

    #FeaturedPost1 .featured-post-more:hover {
      background: var(--color-hover);
    }


    /* --------------------------------------------------
       Featured Post Mobile
       -------------------------------------------------- */

    @media (max-width: 800px) {

      #FeaturedPost1 {
        margin-bottom: 36px;
        padding: 20px 20px 24px;
      }

      #FeaturedPost1 > .title {
        margin-bottom: 20px;
      }

      #FeaturedPost1 .post-summary {
        display: block;
      }

      #FeaturedPost1 .post-summary .image {
        width: 100%;
        height: auto;
        max-height: 320px;

        margin-bottom: 20px;
      }

      #FeaturedPost1 .post-summary h3 {
        margin-bottom: 16px;
        font-size: 1.3rem;
      }

      #FeaturedPost1 .featured-post-abstract {
        font-size: 0.92rem;
        line-height: 1.8;
      }

    }


    /* ==================================================
       FOOTER
       ================================================== */

    .site-footer {
      margin-top: 64px;
      background: #07273b;
      border-top: 1px solid #cccccc;
    }

    /* ==================================================
       FOOTER WIDGETS
       記事ページのみ
       ================================================== */

    .footer-widgets {
      background: #cccccc;
      padding:
        32px
        var(--header-padding-right)
        24px
        var(--header-padding-left);
    }

    .footer-widgets-inner {
      max-width: var(--site-max-width);
      margin: 0 auto;

      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 32px;
    }

    .footer-widgets-inner > .section {
      min-width: 0;
    }

    /* ==================================================
       FOOTER WIDGET CARDS
       ================================================== */

    .footer-widget,
    .footer-widgets-inner > .section {
      background: #fcfcfc;
      border: 1px solid #cccccc;
      padding: 20px;
      box-sizing: border-box;
      color: #202122;
    }

    .footer-widgets-inner h2 {
      margin: 0 0 14px;
      padding-bottom: 8px;

      color: #202122;
      font-size: 1rem;
      font-weight: 700;
      line-height: 1.4;

      border-bottom: 1px solid #c8ccd1;
    }

    .footer-widgets-inner a {
      color: #0645ad;
    }

    .footer-widgets-inner .item-snippet,
    .footer-widgets-inner .popular-post-abstract,
    .footer-widgets-inner .post-count,
    .footer-widgets-inner .label-count {
      color: #54595d;
    }

    /* ==================================================
       FOOTER POPULAR POSTS
       ================================================== */

    .footer-widgets-inner .popular-posts ul {
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .footer-widgets-inner .popular-posts li {
      position: relative;

      display: block;

      margin: 0 0 var(--popular-post-item-margin-bottom);
      padding: 0 0 var(--popular-post-item-margin-bottom);

      border-bottom: 1px solid var(--color-border);
    }

    .footer-widgets-inner .popular-posts li:last-child {
      margin-bottom: 0;
      padding-bottom: 0;
      border-bottom: 0;
    }

    .footer-widgets-inner .popular-posts .item-title {
      margin: 0;
      font-size: var(--popular-post-title-size);
      line-height: var(--popular-post-title-line-height);
    }

    .footer-widgets-inner .popular-posts .item-title a {
      color: var(--color-link);
      text-decoration: none;
      font-weight: var(--popular-post-title-weight);
    }

    .footer-widgets-inner .popular-post-abstract,
    .footer-widgets-inner .popular-posts .item-snippet {
      margin-top: 4px;
      color: var(--color-text);
      font-size: var(--popular-post-abstract-size);
      line-height: var(--popular-post-abstract-line-height);
    }

    .footer-widgets-inner .popular-posts .item-thumbnail {
      float: right;
      width: var(--popular-post-thumbnail-width);
      margin: 0 0 4px var(--popular-post-item-gap);
    }

    .footer-widgets-inner .popular-posts .item-thumbnail img {
      display: block;
      width: 100%;
      height: var(--popular-post-thumbnail-height);
      object-fit: cover;
    }

    /* ==================================================
       FOOTER LINKS
       全ページ表示
       ================================================== */

    .site-footer-inner {
      max-width: var(--site-max-width);
      margin: 0 auto;

      padding:
        28px
        var(--header-padding-right)
        28px
        var(--header-padding-left);

      display: flex;
      justify-content: center;
      align-items: center;
    }

    .footer-links {
      display: flex;
      align-items: center;
      gap: 20px;
    }

    .footer-links a {
      color: #f2f4f5;
      font-size: 0.9rem;
      font-weight: 600;
      text-decoration: none;
    }

    .footer-links a:hover {
      text-decoration: underline;
    }


    /* ==================================================
       RESPONSIVE
       ================================================== */

    /* --------------------------------------------------
       Article Gallery - Mobile
       -------------------------------------------------- */

    @media (max-width: 800px) {

      .article-gallery-item {
        flex-basis: 180px;
      }

      .article-gallery-item img {
        height: 140px;
      }

    }

    @media (max-width: 500px) {

      .article-gallery-item {
        flex-basis: 160px;
      }

      .article-gallery-item img {
        height: 130px;
      }

    }


    /* --------------------------------------------------
       Image Modal - Mobile
       -------------------------------------------------- */

    @media (max-width: 800px) {

      .image-modal {
        padding: 12px;
      }

      .image-modal img {
        max-width: 96vw;
        max-height: 85vh;
      }

      .image-modal-caption {
        left: 12px;
        right: 12px;
        bottom: 10px;
        max-width: calc(100vw - 24px);
        font-size: 0.8rem;
      }

    }


    /* --------------------------------------------------
       Article References - Mobile
       -------------------------------------------------- */

    @media (max-width: 800px) {

      .article-ref-preview,
      .article-reference-preview {
        width: 260px;
        max-width: calc(100vw - 32px);
      }

    }


    /* --------------------------------------------------
       Global Mobile Layout
       -------------------------------------------------- */

    @media (max-width: 800px) {

      .header-inner {
        flex-wrap: wrap;
      }

      .site-layout {
        display: block;

        padding: var(--mobile-layout-padding);
      }

      .contents {
        position: static;

        margin-bottom: var(--mobile-contents-margin-bottom);

        padding: var(--mobile-contents-padding);

        border: 1px solid var(--color-border-light);

        background: var(--color-surface);
      }

      .article-title {
        font-size: var(--mobile-article-title-size);
      }

      .home-main {
        max-width: none;
      }

      .infobox {
        float: none;

        width: 100%;

        margin:
          0
          0
          var(--mobile-infobox-margin-bottom);
      }

      .article-body pre[class*="language-"] {
        padding: var(--mobile-code-padding);
      }

      .article-body pre[class*="language-"] > code {
        font-size: var(--mobile-code-font-size);
      }

    }


    /* --------------------------------------------------
       Article List - Mobile
       -------------------------------------------------- */

    @media (max-width: 800px) {
      .article-list-item {
        grid-template-columns: 1fr;
        gap: 16px;
      }

      .article-list-thumbnail-container {
        justify-content: flex-start;
      }

      .article-list-thumbnail {
        justify-content: flex-start;
      }

      .article-list-thumbnail img {
        max-width: 100%;
        max-height: var(--article-list-mobile-thumbnail-max-height);
      }
    }


    /* ==================================================
       CATEGORY PAGE
       ================================================== */

    /* ==================================================
       CATEGORY LIST
       ================================================== */

        #Label2 ul {
          margin: 24px 0 0;
          padding: 0;
          list-style: none;
        }

        #Label2 li {
          margin: 0;
          padding: 12px 0;
        }

        #Label2 a {
          color: var(--color-link);
          text-decoration: none;
        }

        #Label2 a:hover {
          text-decoration: underline;
        }

/* ==================================================
   HEADER
   ================================================== */

/* ==================================================
   HEADER PARAMETERS
   ================================================== */

:root {
  /* --------------------------------------------------
     Header
     -------------------------------------------------- */
  --header-border-color: #5B858B;
  --header-border-width: 1px;

  /* --------------------------------------------------
     Header Section
     -------------------------------------------------- */
  --header-section-max-width: var(--site-max-width);

  /* --------------------------------------------------
     Search
     -------------------------------------------------- */
  --header-search-padding-top: 8px;
  --header-search-padding-bottom: 8px;
  --header-search-width: var(--search-max-width);
  --header-search-height: 36px;
  --header-search-input-padding-x: 10px;
  --header-search-input-padding-y: 7px;
  --header-search-button-width: 56px;
  --header-search-button-padding-x: 12px;
  --header-search-input-size: var(--search-input-size);
  --header-search-button-size: 0.8rem;
  --header-search-border-color: #d8dde1;
  --header-search-background: #fff;
  --header-search-button-background: #f2f4f5;
  --header-search-button-color: #3f4a52;

  /* --------------------------------------------------
     Brand
     -------------------------------------------------- */
  --header-brand-padding-top: 32px;
  --header-brand-padding-bottom: 32px;
  --header-title-size: 2.4rem;
  --header-title-weight: var(--site-title-weight);
  --header-title-line-height: 1.2;
  --header-title-color: #07273b;

  /* --------------------------------------------------
     Header Navigation
     -------------------------------------------------- */
  --header-navigation-background: #07273b;
  --header-navigation-padding-top: 10px;
  --header-navigation-padding-bottom: 10px;
  --header-navigation-gap: 32px;

  /* --------------------------------------------------
     Page List
     -------------------------------------------------- */
  --header-page-list-font-size: 0.9rem;
  --header-page-list-font-weight: 600;
  --header-page-list-line-height: 1.5;
  --header-page-list-padding-x: 0;
  --header-page-list-padding-y: 0;
  --header-page-list-link-padding-x: 0;
  --header-page-list-link-padding-y: 0;
  --header-page-list-color: #fff;
  --header-page-list-hover-color: #fff;

  /* --------------------------------------------------
     Share
     -------------------------------------------------- */
  --header-share-font-size: 0.9rem;
  --header-share-font-weight: 600;
  --header-share-color: #fff;
  --header-share-menu-width: 170px;
  --header-share-menu-offset: 8px;
  --header-share-menu-background: #fff;
  --header-share-menu-border-color: #c8ced2;
  --header-share-item-padding-x: 14px;
  --header-share-item-padding-y: 6px;
  --header-share-item-min-height: 34px;
  --header-share-item-size: 0.88rem;
  --header-share-item-color: #222;
  --header-share-item-hover-background: #f1f3f4;
  --header-share-item-hover-color: #000;

  /* --------------------------------------------------
     Header Tools
     RSS / リンクコピー
     -------------------------------------------------- */
  --header-tools-gap: 8px;
  --header-tools-height: 36px;
  --header-tool-size: 20px;
  --header-tool-button-size: 24px;
  --header-tool-icon-stroke-width: 3;
  --header-tools-padding-right: 32px;
  --header-tools-status-offset: 30px;
  --header-tools-status-size: 0.75rem;
  --header-tools-color: #fff;
}

/* ==================================================
   HEADER BASE
   ================================================== */

.site-header {
  position: relative;
  border-bottom: var(--header-border-width) solid var(--header-border-color);
}

/* ==================================================
   HEADER SECTION
   ================================================== */

.header-section {
  width: 100%;
  max-width: var(--header-section-max-width);
  margin: 0 auto;
}

.header-section > .widget {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  margin: 0;
}

/* ==================================================
   HEADER SEARCH
   ================================================== */

.header-section #BlogSearch1 {
  width: var(--header-search-width);
  padding: var(--header-search-padding-top) 0 var(--header-search-padding-bottom);
}

.header-section #BlogSearch1 > .title {
  display: none;
}

.header-section #BlogSearch1 .widget-content {
  width: 100%;
}

.header-section #BlogSearch1 form.gsc-search-box {
  width: 100%;
  margin: 0;
  padding: 0;
}

.header-section #BlogSearch1 table.gsc-search-box {
  width: 100%;
  margin: 0;
  padding: 0;
  border-collapse: collapse;
}

.header-section #BlogSearch1 td.gsc-input {
  padding: 0;
}

.header-section #BlogSearch1 input.gsc-input {
  box-sizing: border-box;
  width: 100%;
  height: var(--header-search-height);
  margin: 0;
  padding: var(--header-search-input-padding-y) var(--header-search-input-padding-x);
  border: 1px solid var(--header-search-border-color);
  background: var(--header-search-background);
  color: var(--color-text);
  font-family: inherit;
  font-size: var(--header-search-input-size);
  line-height: 1.4;
}

.header-section #BlogSearch1 td.gsc-search-button {
  width: var(--header-search-button-width);
  padding: 0 0 0 6px;
}

.header-section #BlogSearch1 input.gsc-search-button {
  box-sizing: border-box;
  width: var(--header-search-button-width);
  height: var(--header-search-height);
  margin: 0;
  padding: var(--header-search-input-padding-y) var(--header-search-button-padding-x);
  border: 1px solid var(--header-search-border-color);
  background: var(--header-search-button-background);
  color: var(--header-search-button-color);
  font-family: inherit;
  font-size: var(--header-search-button-size);
  line-height: 1.4;
  cursor: pointer;
}

.header-section #BlogSearch1 input.gsc-search-button:hover {
  background: var(--color-hover);
}

/* ==================================================
   HEADER BRAND
   ================================================== */

.header-section #Header1 {
  position: relative;
  padding: var(--header-brand-padding-top) 0 var(--header-brand-padding-bottom);
  background: var(--color-page);
}

.header-section #Header1 #header-inner {
  position: relative;
  width: 100%;
  min-width: 0;
  margin: 0;
  padding: 0;
  background-position: center;
  background-repeat: no-repeat;
  background-size: cover;
}

.header-section #Header1 .titlewrapper {
  margin: 0;
  padding: 0;
  background: transparent;
}

.header-section #Header1 h1.title {
  margin: 0;
  color: var(--header-title-color);
  font-family: inherit;
  font-size: var(--header-title-size);
  font-weight: var(--header-title-weight);
  line-height: var(--header-title-line-height);
  text-align: center;
}

.header-section #Header1 h1.title a {
  color: inherit;
  text-decoration: none;
}

.header-section #Header1 h1.title a:hover {
  text-decoration: underline;
}

.header-section #Header1 .descriptionwrapper {
  margin-top: 8px;
}

.header-section #Header1 .description {
  margin: 0;
  color: var(--color-muted);
  font-family: inherit;
  font-size: 0.85rem;
  line-height: 1.7;
  text-align: center;
}

/* ==================================================
   HEADER PAGE LIST
   ================================================== */

.header-section #PageList1 {
  position: relative;
  width: 100vw;
  margin-left: calc((var(--header-section-max-width) - 100vw) / 2);
  padding: var(--header-navigation-padding-top) 0 var(--header-navigation-padding-bottom);
  border-top: var(--header-border-width) solid var(--header-border-color);
  background: var(--header-navigation-background);
}

.header-section #PageList1 > h2 {
  display: none;
}

.header-section #PageList1 .widget-content {
  width: var(--header-section-max-width);
  max-width: 100%;
  margin: 0 auto;
  padding: 0;
}

.header-section #PageList1 ul {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--header-navigation-gap);
  margin: 0;
  padding: 0 32px;
  list-style: none;
}

.header-section #PageList1 li {
  margin: 0;
  padding: 0;
}

.header-section #PageList1 li a {
  display: block;
  padding: var(--header-page-list-link-padding-y) var(--header-page-list-link-padding-x);
  color: var(--header-page-list-color);
  font-family: inherit;
  font-size: var(--header-page-list-font-size);
  font-weight: var(--header-page-list-font-weight);
  line-height: var(--header-page-list-line-height);
  text-decoration: none;
}

.header-section #PageList1 li a:hover {
  color: var(--header-page-list-hover-color);
  text-decoration: underline;
}

.header-section #PageList1 li.selected a {
  font-weight: var(--header-page-list-font-weight);
}

/* ==================================================
   HEADER SHARE
   ================================================== */

.header-share {
  position: relative;
  flex-shrink: 0;
  white-space: nowrap;
}

.header-share-button {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 0;
  border: 0;
  background: transparent;
  color: var(--header-share-color);
  cursor: pointer;
  font-family: inherit;
  font-size: var(--header-share-font-size);
  font-weight: var(--header-share-font-weight);
  line-height: 1.4;
}

.header-share-button:hover {
  text-decoration: underline;
}

.header-share-arrow {
  font-size: 0.7rem;
  line-height: 1;
  opacity: 0.8;
}

/* ==================================================
   SHARE MENU
   ================================================== */

.header-share-menu {
  position: absolute;
  top: calc(100% + var(--header-share-menu-offset));
  right: 0;
  z-index: 1000;
  display: none;
  min-width: var(--header-share-menu-width);
  padding: 5px 0;
  background: var(--header-share-menu-background);
  border: 1px solid var(--header-share-menu-border-color);
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.15);
}

.header-share.is-open .header-share-menu {
  display: block;
}

/* ==================================================
   SHARE ITEMS
   ================================================== */

.header-share-menu .header-share-item {
  display: flex;
  align-items: center;
  width: 100%;
  box-sizing: border-box;
  min-height: var(--header-share-item-min-height);
  padding: var(--header-share-item-padding-y) var(--header-share-item-padding-x);
  border: 0;
  background: var(--header-share-menu-background);
  color: var(--header-share-item-color) !important;
  font-family: inherit;
  font-size: var(--header-share-item-size);
  font-weight: 400;
  line-height: 1.4;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
}

.header-share-menu .header-share-item:hover {
  background: var(--header-share-item-hover-background);
  color: var(--header-share-item-hover-color) !important;
}

.header-share-item-label {
  white-space: nowrap;
}

/* ========================================
   Header tools
   RSS / リンクコピー
   ======================================== */

.header-section #HTML1 {
  position: absolute;
  right: calc((100% - var(--header-section-max-width)) / 2);
  bottom: 0;
  z-index: 20;
  width: auto;
  margin: 0;
  padding: 0;
}

.header-section #HTML1 .widget-content {
  margin: 0;
  padding: 0;
}

.header-tools {
  display: flex;
  align-items: center;
  gap: var(--header-tools-gap);
  height: var(--header-tools-height);
  margin: 0;
  padding: 0 var(--header-tools-padding-right) 0 0;
}

.header-tool-link,
.header-tool-copy {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--header-tool-button-size);
  height: var(--header-tool-button-size);
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--header-tools-color);
  cursor: pointer;
  text-decoration: none;
}

.header-tool-icon {
  display: block;
  width: var(--header-tool-size);
  height: var(--header-tool-size);
  fill: none;
  stroke: currentColor;
  stroke-width: var(--header-tool-icon-stroke-width);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.header-tool-link:hover,
.header-tool-copy:hover {
  color: var(--header-tools-color);
  opacity: 0.7;
}

.header-copy-status {
  position: absolute;
  right: 0;
  top: calc(100% + 8px);
  z-index: 30;

  box-sizing: border-box;
  padding: 6px 10px;

  white-space: nowrap;

  font-size: var(--header-tools-status-size);
  line-height: 1.4;
  color: #222;

  background: #fff;
  border: 1px solid #c8ced2;
  border-radius: 4px;

  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12);

  pointer-events: none;

  opacity: 0;
  visibility: hidden;

  transition:
    opacity 0.25s ease,
    visibility 0.25s ease;
}

/* ==================================================
   HEADER MOBILE
   ================================================== */

@media (max-width: 700px) {
  /* --------------------------------------------------
     Search
     -------------------------------------------------- */

  .header-section #BlogSearch1 {
    padding-top: 8px;
    padding-bottom: 8px;
  }

  /* --------------------------------------------------
     Brand
     -------------------------------------------------- */

  .header-section #Header1 {
    padding-top: 24px;
    padding-bottom: 24px;
  }

  .header-section #Header1 h1.title {
    font-size: 1.8rem;
  }

  /* --------------------------------------------------
     Page List
     -------------------------------------------------- */

  .header-section #PageList1 {
    padding-top: 8px;
    padding-bottom: 8px;
  }

  .header-section #PageList1 ul {
    gap: 12px;
  }

  .header-section #PageList1 li a {
    font-size: 0.84rem;
  }

  /* --------------------------------------------------
     Header description
     -------------------------------------------------- */

  .header-section #Header1 .description {
    font-size: 0.8rem;
  }
}

