body.script:
//

/* ===================================
  Contents JS
  ====================================== */

document.addEventListener("DOMContentLoaded", function () {

  /*
   * Contents生成
   */
  function buildContents() {

    const article =
      document.querySelector(".article-body");

    const contents =
      document.querySelector(".contents nav");

    if (!article || !contents) {
      return;
    }

    /*
     * 見出しを取得
     *
     * Galleryの見出しも
     * 実際のh2として取得する
     */
    const headings =
      Array.from(
        article.querySelectorAll("h2, h3")
      );

    /*
     * Gallery
     *
     * article-bodyの外にあるため追加
     */
    const galleryTitle =
      document.querySelector(
        ".article-gallery-title"
      );

    if (galleryTitle && !headings.includes(galleryTitle)) {
      headings.push(galleryTitle);
    }

    /*
     * 見出しがない場合
     */
    const contentsBox =
      document.querySelector(".contents");

    if (!headings.length) {

      if (contentsBox) {
        contentsBox.style.display = "none";
      }

      return;
    }

    if (contentsBox) {
      contentsBox.style.display = "";
    }

    /*
     * 以前付けた番号を一度元に戻す
     *
     * Contentsを再生成しても
     * 1. 1. 1. のようにならないようにする
     */
    headings.forEach(function (heading) {

      if (heading.dataset.contentsTitle) {
        heading.textContent =
          heading.dataset.contentsTitle;
      } else {
        heading.dataset.contentsTitle =
          heading.textContent.trim();
      }

    });

    /*
     * Contents生成
     */
    const list =
      document.createElement("ul");

    let h2Count = 0;
    let h3Count = 0;

    headings.forEach(function (heading) {

      const level =
        heading.tagName.toLowerCase();

      const originalTitle =
        heading.dataset.contentsTitle ||
        heading.textContent.trim();

      /*
       * ID
       */
      const id =
        heading.id ||
        (
          "section-" +
          Math.random()
            .toString(36)
            .substring(2, 10)
        );

      heading.id = id;

      const li =
        document.createElement("li");

      const link =
        document.createElement("a");

      link.href =
        "#" + id;

      /*
       * H2
       */
      if (level === "h2") {

        h2Count++;
        h3Count = 0;

        const cleanTitle =
          originalTitle.replace(
            /^\d+\.\s*/,
            ""
          );

        const number =
          h2Count + ".";

        heading.textContent =
          number + " " + cleanTitle;

        link.textContent =
          number + " " + cleanTitle;
      }

      /*
       * H3
       */
      else if (level === "h3") {

        h3Count++;

        const cleanTitle =
          originalTitle.replace(
            /^\d+\.\d+\s*/,
            ""
          );

        const number =
          h2Count + "." + h3Count;

        heading.textContent =
          number + " " + cleanTitle;

        link.textContent =
          number + " " + cleanTitle;

        li.classList.add("level-2");
      }

      li.appendChild(link);
      list.appendChild(li);

    });

    /*
     * Contentsを入れ替え
     */
    contents.innerHTML = "";
    contents.appendChild(list);

  }

  /*
   * 外部からContentsを再生成できるようにする
   */
  window.buildArticleContents = buildContents;


  /*
   * 最初にContentsを作る
   */
  buildContents();

  /*
   * Gallery生成後
   */
  document.addEventListener(
    "articleGalleryReady",
    function () {
      buildContents();
    }
  );

  /*
   * Contentsクリック
   */
  const contents =
    document.querySelector(".contents nav");

  if (contents) {

    contents.addEventListener(
      "click",
      function (event) {

        const link =
          event.target.closest(
            "a[href^='#']"
          );

        if (!link) {
          return;
        }

        const hash =
          link.getAttribute("href");

        if (!hash || hash === "#") {
          return;
        }

        const target =
          document.querySelector(hash);

        if (!target) {
          return;
        }

        event.preventDefault();

        const offset = 80;

        const targetPosition =
          target.getBoundingClientRect().top +
          window.pageYOffset -
          offset;

        window.scrollTo({
          top: targetPosition,
          behavior: "smooth"
        });

        history.replaceState(
          null,
          "",
          hash
        );

      }
    );

  }

  /*
   * ページ先頭へ
   */
  const contentsTop =
    document.querySelector(
      ".contents-top-link"
    );

  if (contentsTop) {

    contentsTop.addEventListener(
      "click",
      function (event) {

        event.preventDefault();

        window.scrollTo({
          top: 0,
          behavior: "smooth"
        });

      }
    );

  }

});

//

//

/* ====================
   ImagesJS
   ==================== */

document.addEventListener("DOMContentLoaded", function () {

  const images =
    document.querySelectorAll(".article-image img");

  if (!images.length) {
    return;
  }

  images.forEach(function (image) {

    image.addEventListener("click", function () {

      const modal =
        document.createElement("div");

      modal.className = "image-modal";

      const modalImage =
        document.createElement("img");

      modalImage.src = image.src;
      modalImage.alt = image.alt || "";

      modal.appendChild(modalImage);

      /*
       * Caption
       */

      const caption =
        image.closest(".article-image")
          ?.querySelector(".article-image-caption");

      if (caption) {

        const modalCaption =
          document.createElement("div");

        modalCaption.className =
          "image-modal-caption";

        modalCaption.textContent =
          caption.textContent;

        modal.appendChild(modalCaption);
      }

      /*
       * Close button
       */

      const close =
        document.createElement("button");

      close.className =
        "image-modal-close";

      close.type = "button";
      close.textContent = "×";
      close.setAttribute("aria-label", "閉じる");

      modal.appendChild(close);

      document.body.appendChild(modal);

      /*
       * Close
       */

      function closeModal() {
        modal.remove();
        document.removeEventListener(
          "keydown",
          handleKeydown
        );
      }

      function handleKeydown(event) {

        if (event.key === "Escape") {
          closeModal();
        }

      }

      close.addEventListener(
        "click",
        function (event) {
          event.stopPropagation();
          closeModal();
        }
      );

      modal.addEventListener(
        "click",
        function (event) {

          if (event.target === modal) {
            closeModal();
          }

        }
      );

      document.addEventListener(
        "keydown",
        handleKeydown
      );

    });

  });

});

