/* ======================
   GalleryJS
   ====================== */

document.addEventListener("DOMContentLoaded", function () {

  const article =
    document.querySelector(".article-body");

  const container =
    document.querySelector(".article-gallery-container");

  if (!article || !container) {
    return;
  }

  const sourceImages =
    article.querySelectorAll(".article-image img");

  if (!sourceImages.length) {
    return;
  }

  /*
   * Gallery
   */

  const gallery =
    document.createElement("section");

  gallery.className =
    "article-gallery";

  /*
   * Gallery title
   */

  const title =
    document.createElement("h2");

  title.className =
    "article-gallery-title";

  title.id =
    "article-gallery";

  title.textContent =
    "Gallery";

  gallery.appendChild(title);

  /*
   * Viewport
   */

  const viewport =
    document.createElement("div");

  viewport.className =
    "article-gallery-viewport";

  /*
   * Track
   */

  const track =
    document.createElement("div");

  track.className =
    "article-gallery-track";

  viewport.appendChild(track);

  /*
   * Images
   */

  sourceImages.forEach(function (sourceImage) {

    const item =
      document.createElement("figure");

    item.className =
      "article-gallery-item";

    const image =
      document.createElement("img");

    image.src =
      sourceImage.src;

    image.alt =
      sourceImage.alt || "";

    const sourceWrapper =
      sourceImage.closest(".article-image");

    const sourceCaption =
      sourceWrapper
        ? sourceWrapper.querySelector(
            ".article-image-caption"
          )
        : null;

    item.appendChild(image);

    if (sourceCaption) {

      const caption =
        document.createElement("figcaption");

      caption.textContent =
        sourceCaption.textContent;

      item.appendChild(caption);

    }

    item.addEventListener(
      "click",
      function () {

        sourceImage.click();

      }
    );

    track.appendChild(item);

  });

  /*
   * Navigation
   */

  const previous =
    document.createElement("button");

  previous.className =
    "article-gallery-prev";

  previous.type =
    "button";

  previous.textContent =
    "‹";

  previous.setAttribute(
    "aria-label",
    "前の画像"
  );

  const next =
    document.createElement("button");

  next.className =
    "article-gallery-next";

  next.type =
    "button";

  next.textContent =
    "›";

  next.setAttribute(
    "aria-label",
    "次の画像"
  );

  viewport.appendChild(previous);
  viewport.appendChild(next);

  gallery.appendChild(viewport);

  container.appendChild(gallery);

  /*
   * Scroll amount
   */

  function getScrollAmount() {

    const item =
      track.querySelector(
        ".article-gallery-item"
      );

    if (!item) {
      return 0;
    }

    const style =
      window.getComputedStyle(track);

    const gap =
      parseFloat(style.gap) || 0;

    return (
      (item.offsetWidth + gap) * 4
    );

  }

  /*
   * Buttons
   */

  function updateButtons() {

    const maxScroll =
      track.scrollWidth -
      track.clientWidth;

    previous.disabled =
      track.scrollLeft <= 1;

    next.disabled =
      track.scrollLeft >=
      maxScroll - 1;

  }

  previous.addEventListener(
    "click",
    function () {

      track.scrollBy({
        left: -getScrollAmount(),
        behavior: "smooth"
      });

    }
  );

  next.addEventListener(
    "click",
    function () {

      track.scrollBy({
        left: getScrollAmount(),
        behavior: "smooth"
      });

    }
  );

  track.addEventListener(
    "scroll",
    updateButtons
  );

  /*
   * Mouse drag
   */

  let isDragging = false;
  let startX = 0;
  let startScrollLeft = 0;

  track.addEventListener(
    "mousedown",
    function (event) {

      isDragging = true;

      track.classList.add(
        "is-dragging"
      );

      startX =
        event.pageX -
        track.offsetLeft;

      startScrollLeft =
        track.scrollLeft;

    }
  );

  track.addEventListener(
    "mouseleave",
    function () {

      isDragging = false;

      track.classList.remove(
        "is-dragging"
      );

    }
  );

  track.addEventListener(
    "mouseup",
    function () {

      isDragging = false;

      track.classList.remove(
        "is-dragging"
      );

    }
  );

  track.addEventListener(
    "mousemove",
    function (event) {

      if (!isDragging) {
        return;
      }

      event.preventDefault();

      const x =
        event.pageX -
        track.offsetLeft;

      const walk =
        (x - startX) * 1.2;

      track.scrollLeft =
        startScrollLeft - walk;

    }
  );

  updateButtons();

  /*
   * ContentsへGallery生成完了を通知
   */

  document.dispatchEvent(
    new CustomEvent("articleGalleryReady")
  );

});

