/**
 * ============================================================
 * Reference Engine
 * ============================================================
 *
 * 本文中のReferenceとTargetを管理する汎用エンジン。
 *
 * 【基本概念】
 *
 *   Target
 *     └─ 参照される対象
 *        例：図、表、記事、数式、コード、参考文献
 *
 *   Reference
 *     └─ 本文中からTargetを参照する要素
 *
 * 【処理の流れ】
 *
 *   1. referenceTypesから各Typeの仕様を取得
 *   2. DOM上のTargetを収集
 *   3. Targetに番号を付ける
 *   4. DOM上のReferenceからTargetを検索
 *   5. Referenceをリンクへ変換
 *   6. 必要に応じてTargetから本文へ戻るリンクを作成
 *   7. 遅れて追加されたDOMをMutationObserverで検知
 *   8. DOM変更が落ち着いた後に再処理
 *
 * Reference Engine本体は、article / fig / tableなどの
 * 個別Typeを特別扱いしない。
 *
 * Type固有の仕様はreferenceTypesだけで定義する。
 *
 * ============================================================
 */


/**
 * ============================================================
 * Reference Type Definition
 * ============================================================
 *
 * 各Reference Typeの仕様をここで定義する。
 *
 * 【label】
 *   Target側に表示する番号の形式。
 *
 * 【refLabel】
 *   本文中のReferenceに表示する番号の形式。
 *
 * 【targetNumbering】
 *   "document"
 *     → Targetが本文に登場する順番で番号を付ける。
 *
 *   "reference"
 *     → 本文中でReferenceされた順番で番号を付ける。
 *
 * 【targetPlacement】
 *   Target番号をどこへ配置するか。
 *
 * 【defaultStyle】
 *   Referenceの通常表示。
 *
 * 【preview】
 *   Referenceにプレビューを表示するか。
 *
 * 【backlink】
 *   TargetからReference本文へ戻るリンクを作るか。
 *
 * 【sectionTitle】
 *   参考文献などのセクションタイトル。
 *
 * ============================================================
 */

const referenceTypes = {

  reference: {
    label: {
      prefix: "[",
      suffix: "]"
    },
    refLabel: {
      prefix: "",
      suffix: ""
    },
    targetNumbering: "reference",
    targetPlacement: "prepend",
    defaultStyle: "sup",
    preview: true,
    backlink: true,
    sectionTitle: "参考文献"
  },

  article: {
    label: {
      prefix: "記事(",
      suffix: ")"
    },
    refLabel: {
      prefix: "記事(",
      suffix: ")"
    },
    targetNumbering: "document",
    targetPlacement: "article-header",
    defaultStyle: "normal",
    preview: true,
    backlink: false
  },

  fig: {
    label: {
      prefix: "図",
      suffix: ""
    },
    refLabel: {
      prefix: "図",
      suffix: ""
    },
    targetNumbering: "document",
    targetPlacement: "figure-title",
    defaultStyle: "normal",
    preview: true,
    backlink: false
  },

  table: {
    label: {
      prefix: "表",
      suffix: ""
    },
    refLabel: {
      prefix: "表",
      suffix: ""
    },
    targetNumbering: "document",
    targetPlacement: "table-title",
    defaultStyle: "normal",
    preview: true,
    backlink: false
  },

  equation: {
    label: {
      prefix: "(",
      suffix: ")"
    },
    refLabel: {
      prefix: "式(",
      suffix: ")"
    },
    targetNumbering: "document",
    targetPlacement: "equation",
    defaultStyle: "normal",
    preview: true,
    backlink: false
  },

  code: {
    label: {
      prefix: "コード例(",
      suffix: ")"
    },
    refLabel: {
      prefix: "コード例(",
      suffix: ")"
    },
    targetNumbering: "document",
    targetPlacement: "prepend",
    defaultStyle: "normal",
    preview: false,
    backlink: false
  },

  video: {
    label: {
      prefix: "動画(",
      suffix: ")"
    },
    refLabel: {
      prefix: "動画(",
      suffix: ")"
    },
    targetNumbering: "document",
    targetPlacement: "video-title",
    defaultStyle: "normal",
    preview: true,
    backlink: false
  }
};


/**
 * ============================================================
 * getLabel
 * ============================================================
 *
 * Typeと番号から表示文字列を生成する。
 *
 * mode:
 *   undefined / "target"
 *     → Target側の表示
 *
 *   "ref"
 *     → 本文Reference側の表示
 *
 * 例：
 *
 *   getLabel("fig", 2)
 *     → 図2
 *
 *   getLabel("article", 3)
 *     → 記事（3）
 *
 *   getLabel("reference", 4, "ref")
 *     → 4
 *
 * ============================================================
 */

function getLabel(type, number, mode) {

  const config = referenceTypes[type];

  if (!config) {
    return "[" + number + "]";
  }

  const label =
    mode === "ref"
      ? config.refLabel
      : config.label;

  return (
    label.prefix +
    number +
    label.suffix
  );
}


/**
 * ============================================================
 * getStyle
 * ============================================================
 *
 * Referenceの表示スタイルを決定する。
 *
 * data-style="sup"
 * data-style="normal"
 *
 * が指定されている場合はそちらを優先する。
 *
 * ============================================================
 */

function getStyle(type, ref) {

  const config = referenceTypes[type];

  if (!config) {
    return "normal";
  }

  const customStyle =
    ref.getAttribute("data-style");

  if (
    customStyle === "sup" ||
    customStyle === "normal"
  ) {
    return customStyle;
  }

  return config.defaultStyle;
}


/**
 * ============================================================
 * scrollToCenter
 * ============================================================
 *
 * ReferenceまたはBacklinkクリック時に、
 * 対象Elementを画面中央付近へスクロールする。
 *
 * ============================================================
 */

function scrollToCenter(element) {

  if (!element) {
    return;
  }

  const rect =
    element.getBoundingClientRect();

  const top =
    rect.top +
    window.pageYOffset -
    (window.innerHeight / 2) +
    (rect.height / 2);

  window.scrollTo({
    top: top,
    behavior: "smooth"
  });
}


/**
 * ============================================================
 * getSourcePreview
 * ============================================================
 *
 * Referenceが存在する本文側の文章を取得する。
 *
 * Reference自身のリンクやプレビューは除外する。
 *
 * ============================================================
 */

function getSourcePreview(ref) {

  if (!ref) {
    return "";
  }

  const paragraph =
    ref.closest("p");

  if (paragraph) {

    const clone =
      paragraph.cloneNode(true);

    clone.querySelectorAll(
      ".article-ref, .article-ref-link"
    ).forEach(function (element) {
      element.remove();
    });

    return clone.textContent.trim();
  }

  if (ref.parentElement) {
    return ref.parentElement.textContent.trim();
  }

  return "";
}


/**
 * ============================================================
 * getTargetPreview
 * ============================================================
 *
 * Target側の本文をReference用プレビューとして取得する。
 *
 * 番号やBacklinkは除外する。
 *
 * ============================================================
 */

function getTargetPreview(target) {

  if (!target) {
    return "";
  }

  const clone =
    target.cloneNode(true);

  clone.querySelectorAll(
    ".article-target-number, .article-reference-back"
  ).forEach(function (element) {
    element.remove();
  });

  return clone.textContent.trim();
}


/**
 * ============================================================
 * createTargetMap
 * ============================================================
 *
 * DOM上のTargetを、
 *
 *   type → label → target[]
 *
 * の構造へ整理する。
 *
 * 例：
 *
 *   fig
 *     ├─ fig-a
 *     └─ fig-b
 *
 *   article
 *     ├─ article-a
 *     └─ article-b
 *
 * ============================================================
 */

function createTargetMap(targets) {

  const targetMap = {};

  targets.forEach(function (target) {

    const label =
      target.getAttribute("data-label");

    const type =
      target.getAttribute("data-type");

    if (!label || !type) {
      return;
    }

    if (!targetMap[type]) {
      targetMap[type] = {};
    }

    if (!targetMap[type][label]) {
      targetMap[type][label] = [];
    }

    targetMap[type][label].push(target);
  });

  return targetMap;
}


/**
 * ============================================================
 * createNumberElement
 * ============================================================
 *
 * Targetに表示する番号Elementを生成する。
 *
 * ============================================================
 */

function createNumberElement(type, number) {

  const numberElement =
    document.createElement("span");

  numberElement.className =
    "article-target-number";

  numberElement.textContent =
    getLabel(type, number);

  return numberElement;
}


/**
 * ============================================================
 * getTargetNumberElement
 * ============================================================
 *
 * Target内に既に存在する番号Elementを取得する。
 *
 * ============================================================
 */

function getTargetNumberElement(target) {

  return target.querySelector(
    ":scope > .article-target-number, .article-target-number"
  );
}


/**
 * ============================================================
 * placeNumberElement
 * ============================================================
 *
 * referenceTypes.targetPlacementの設定に従って、
 * Target番号を適切な場所へ配置する。
 *
 * この関数自体はType名を判断しない。
 *
 * Type固有の違いはtargetPlacementで定義する。
 *
 * ============================================================
 */

function placeNumberElement(
  target,
  numberElement,
  config
) {

  const placement =
    config.targetPlacement;


  /*
   * article-header
   */

  if (
    placement === "article-header"
  ) {

    const header =
      target.querySelector(
        ".article-ref-header"
      );

    if (header) {

      if (
        !header.contains(
          numberElement
        )
      ) {
        header.prepend(
          numberElement
        );
      }

    } else if (
      !target.contains(
        numberElement
      )
    ) {

      target.prepend(
        numberElement
      );

    }

    return;
  }


  /*
   * figure-title
   */

  if (
    placement === "figure-title"
  ) {

    const title =
      target.querySelector(
        ".article-figure-title"
      );

    const caption =
      target.querySelector(
        "figcaption"
      );

    if (title) {

      if (
        !title.contains(
          numberElement
        )
      ) {
        title.prepend(
          numberElement
        );
      }

    } else if (caption) {

      if (
        !caption.contains(
          numberElement
        )
      ) {
        caption.prepend(
          numberElement
        );
      }

    } else if (
      !target.contains(
        numberElement
      )
    ) {

      target.prepend(
        numberElement
      );

    }

    return;
  }


  /*
   * table-title
   */

  if (
    placement === "table-title"
  ) {

    const title =
      target.querySelector(
        ".article-table-title"
      );

    if (title) {

      if (
        !title.contains(
          numberElement
        )
      ) {
        title.prepend(
          numberElement
        );
      }

    } else if (
      !target.contains(
        numberElement
      )
    ) {

      target.prepend(
        numberElement
      );

    }

    return;
  }


  /*
   * equation
   */

  if (
    placement === "equation"
  ) {

    const equation =
      target.querySelector(
        ".article-equation"
      );

    if (equation) {

      if (
        !equation.contains(
          numberElement
        )
      ) {
        equation.appendChild(
          numberElement
        );
      }

    } else if (
      !target.contains(
        numberElement
      )
    ) {

      target.appendChild(
        numberElement
      );

    }

    return;
  }

  /*
   * video
   */

  if (
    placement === "video-title"
  ) {
    const title =
      target.querySelector(
        ".article-video-title"
      );

    if (title) {
      if (
        !title.contains(
          numberElement
        )
      ) {
        title.prepend(
          numberElement
        );
      }
    } else if (
      !target.contains(
        numberElement
      )
    ) {
      target.appendChild(
        numberElement
      );
    }

    return;
  }


  /*
   * prepend
   *
   * デフォルト位置。
   */

  if (
    !target.contains(
      numberElement
    )
  ) {
    target.prepend(
      numberElement
    );
  }
}


/**
 * ============================================================
 * numberDocumentTargets
 * ============================================================
 *
 * targetNumbering="document" のTypeを処理する。
 *
 * Targetが本文中に登場した順番で番号を付ける。
 *
 * 同じdata-labelを持つTargetは同じ番号を使用する。
 *
 * 重要：
 *
 * この関数はarticle / fig / tableなどのType名を
 * 一切直接参照しない。
 *
 * ============================================================
 */

function numberDocumentTargets(targetMap) {

  Object.keys(referenceTypes).forEach(function (type) {

    const config =
      referenceTypes[type];

    if (
      config.targetNumbering !==
      "document"
    ) {
      return;
    }

    if (!targetMap[type]) {
      return;
    }

    const targets =
      Array.from(
        document.querySelectorAll(
          "[data-type='" +
          type +
          "'][data-label]"
        )
      );

    let number = 0;

    const numberedLabels = {};

    targets.forEach(function (target) {

      const label =
        target.getAttribute(
          "data-label"
        );

      if (!label) {
        return;
      }


      /*
       * 同じLabelは同じ番号。
       */

      if (
        !Object.prototype.hasOwnProperty.call(
          numberedLabels,
          label
        )
      ) {

        number++;

        numberedLabels[label] =
          number;
      }


      const targetNumber =
        numberedLabels[label];

      target.dataset.number =
        targetNumber;


      /*
       * 既存番号を再利用する。
       */

      let numberElement =
        getTargetNumberElement(
          target
        );

      if (!numberElement) {

        numberElement =
          createNumberElement(
            type,
            targetNumber
          );

      } else {

        numberElement.textContent =
          getLabel(
            type,
            targetNumber
          );
      }


      /*
       * Type定義に従って配置する。
       */

      placeNumberElement(
        target,
        numberElement,
        config
      );

    });
  });
}


/**
 * ============================================================
 * getExistingSourceCount
 * ============================================================
 *
 * 既に生成済みのReference Linkを調べ、
 * 同じTargetに対するReference数を取得する。
 *
 * 遅延DOMによってReference Engineが再実行されても、
 * Source IDが重複しないようにする。
 *
 * ============================================================
 */

function getExistingSourceCount(
  type,
  label
) {

  const links =
    document.querySelectorAll(
      ".article-ref-link[data-type='" +
      type +
      "'][data-ref='" +
      label +
      "']"
    );

  return links.length;
}


/**
 * ============================================================
 * numberReferenceTargets
 * ============================================================
 *
 * 未処理の.article-refを本文側リンクへ変換する。
 *
 * Targetが
 *
 *   targetNumbering="reference"
 *
 * の場合はReference登場順で番号を決定。
 *
 * Targetが
 *
 *   targetNumbering="document"
 *
 * の場合はTarget側で既に決定された番号を使用する。
 *
 * ============================================================
 */

function numberReferenceTargets(
  refs,
  targetMap
) {

  const referenceNumbers = {};
  let referenceNumber = 0;


  refs.forEach(function (ref) {

    const label =
      ref.getAttribute(
        "data-ref"
      );

    const type =
      ref.getAttribute(
        "data-type"
      );

    if (
      !label ||
      !type
    ) {
      return;
    }


    const config =
      referenceTypes[type];

    if (!config) {

      ref.textContent =
        "[?]";

      return;
    }


    const typeMap =
      targetMap[type];

    if (
      !typeMap ||
      !typeMap[label] ||
      !typeMap[label].length
    ) {

      ref.textContent =
        "[?]";

      return;
    }


    const target =
      typeMap[label][0];


    /*
     * =========================
     * Number
     * =========================
     */

    let number;


    /*
     * Reference登場順。
     */

    if (
      config.targetNumbering ===
      "reference"
    ) {

      if (
        !Object.prototype.hasOwnProperty.call(
          referenceNumbers,
          label
        )
      ) {

        referenceNumber++;

        referenceNumbers[label] =
          referenceNumber;
      }

      number =
        referenceNumbers[label];

    }


    /*
     * Target登場順。
     */

    else {

      number =
        target.dataset.number;
    }


    /*
     * 番号がまだ確定していない場合は、
     * 今回は処理せず次回へ回す。
     */

    if (
      number === undefined ||
      number === null ||
      number === ""
    ) {
      return;
    }


    /*
     * =========================
     * Target ID
     * =========================
     */

    if (!target.id) {

      target.id =
        "article-target-" +
        type +
        "-" +
        number;
    }

    const targetId =
      target.id;


    /*
     * =========================
     * Source ID
     * =========================
     */

    const existingCount =
      getExistingSourceCount(
        type,
        label
      );

    const sourceId =
      "article-ref-source-" +
      type +
      "-" +
      number +
      "-" +
      (existingCount + 1);


    /*
     * =========================
     * Preview
     * =========================
     */

    const previewSetting =
      ref.getAttribute(
        "data-preview"
      );

    let showPreview =
      config.preview;

    if (
      previewSetting === "on"
    ) {
      showPreview = true;
    }

    if (
      previewSetting === "off"
    ) {
      showPreview = false;
    }


    const sourcePreview =
      showPreview
        ? getSourcePreview(ref)
        : "";

    const targetPreview =
      showPreview
        ? getTargetPreview(target)
        : "";


    /*
     * =========================
     * 本文側Link
     * =========================
     */

    const link =
      document.createElement("a");

    link.href =
      "#" + targetId;

    link.id =
      sourceId;

    link.className =
      "article-ref-link";

    link.dataset.ref =
      label;

    link.dataset.type =
      type;


    /*
     * Superscript
     */

    if (
      getStyle(type, ref) ===
      "sup"
    ) {

      link.classList.add(
        "is-superscript"
      );
    }


    /*
     * Label
     */

    link.appendChild(
      document.createTextNode(
        getLabel(
          type,
          number,
          "ref"
        )
      )
    );


    /*
     * Target Preview
     */

    if (targetPreview) {

      const preview =
        document.createElement(
          "span"
        );

      preview.className =
        "article-ref-preview";

      preview.textContent =
        targetPreview;

      link.appendChild(
        preview
      );
    }


    /*
     * Reference置換
     */

    if (ref.parentNode) {

      ref.parentNode.replaceChild(
        link,
        ref
      );
    }


    /*
     * =========================
     * Target → 本文
     * =========================
     *
     * backlink=trueの場合のみ生成。
     */

    if (
      config.backlink
    ) {

      const backLink =
        document.createElement(
          "a"
        );

      backLink.href =
        "#" + sourceId;

      backLink.className =
        "article-reference-back";

      backLink.textContent =
        "本文へ";


      if (sourcePreview) {

        const preview =
          document.createElement(
            "span"
          );

        preview.className =
          "article-reference-preview";

        preview.textContent =
          sourcePreview;

        backLink.appendChild(
          preview
        );
      }


      /*
       * 同じBacklinkが既に存在する場合は追加しない。
       */

      const existingBackLink =
        target.querySelector(
          ".article-reference-back[href='#" +
          sourceId +
          "']"
        );

      if (!existingBackLink) {

        target.appendChild(
          backLink
        );
      }
    }

  });
}


/**
 * ============================================================
 * buildSectionTitle
 * ============================================================
 *
 * referenceTypesにsectionTitleが定義されている場合、
 * 参考文献セクションへタイトルを追加する。
 *
 * ============================================================
 */

function buildSectionTitle() {

  const references =
    document.querySelector(
      ".article-references"
    );

  if (!references) {
    return;
  }

  if (
    references.querySelector(
      ".article-reference-section-title"
    )
  ) {
    return;
  }


  let titleText = "";

  Object.keys(
    referenceTypes
  ).forEach(function (type) {

    const config =
      referenceTypes[type];

    if (
      config.sectionTitle &&
      !titleText
    ) {

      titleText =
        config.sectionTitle;
    }
  });


  if (!titleText) {
    return;
  }


  const title =
    document.createElement("h2");

  title.className =
    "article-reference-section-title";

  title.textContent =
    titleText;

  references.insertBefore(
    title,
    references.firstChild
  );
}


/**
 * ============================================================
 * rebuildContents
 * ============================================================
 *
 * Reference処理後に記事Contentsを再構築する。
 *
 * ============================================================
 */

function rebuildContents() {

  if (
    typeof window.buildArticleContents ===
    "function"
  ) {

    window.buildArticleContents();
  }
}


/**
 * ============================================================
 * setupClickHandler
 * ============================================================
 *
 * Reference Link / Backlinkクリック時の
 * スクロール処理を一度だけ登録する。
 *
 * ============================================================
 */

function setupClickHandler() {

  if (
    window.__articleReferenceClickHandler
  ) {
    return;
  }

  window.__articleReferenceClickHandler =
    true;


  document.addEventListener(
    "click",
    function (event) {

      const element =
        event.target;

      if (
        !element ||
        !element.closest
      ) {
        return;
      }


      const link =
        element.closest(
          ".article-ref-link, .article-reference-back"
        );

      if (!link) {
        return;
      }


      const href =
        link.getAttribute(
          "href"
        );

      if (
        !href ||
        href.charAt(0) !== "#"
      ) {
        return;
      }


      const id =
        href.substring(1);

      const target =
        document.getElementById(id);

      if (!target) {
        return;
      }


      event.preventDefault();
      event.stopPropagation();


      scrollToCenter(
        target
      );


      try {

        history.replaceState(
          null,
          "",
          href
        );

      } catch (error) {}

    },
    true
  );
}


function process() {

  const targets =
    document.querySelectorAll(
      "[data-type][data-label]"
    );

  const refs =
    document.querySelectorAll(
      ".article-ref"
    );


  if (
    !targets.length &&
    !refs.length
  ) {
    return;
  }


  /*
   * Target整理
   */

  const targetMap =
    createTargetMap(
      targets
    );


  /*
   * document順のTarget番号を確定。
   */

  numberDocumentTargets(
    targetMap
  );


  /*
   * 本文Referenceを処理。
   */

  numberReferenceTargets(
    refs,
    targetMap
  );


  /*
   * 参考文献タイトル。
   */

  buildSectionTitle();

    /*
   * Contents更新。
   */
  rebuildContents();
}


/**
 * ============================================================
 * setupObserver
 * ============================================================
 *
 * ページ内の遅延DOM生成を監視する。
 *
 * MutationObserverによる大量の連続変更を
 * 100ms単位でまとめて処理する。
 *
 * これにより、
 *
 *   DOM変更
 *   DOM変更
 *   DOM変更
 *   DOM変更
 *
 * のたびにReference Engineを実行することを防ぐ。
 *
 * ============================================================
 */

/**
 * DOM変更を監視し、外部からの変更があった場合にReference Engineを再実行する。
 * Engine自身が行うDOM変更は監視対象から一時的に外す。
 */
function setupObserver() {
  let timer = null;

  const observer =
    new MutationObserver(
      function () {

        if (timer) {
          clearTimeout(timer);
        }

        timer =
          setTimeout(
            function () {

              /*
               * Engine自身のDOM変更を
               * MutationObserverが拾わないようにする。
               */
              observer.disconnect();

              process();

              /*
               * 処理完了後に監視を再開。
               */
              observer.observe(
                document.body,
                {
                  childList: true,
                  subtree: true
                }
              );

            },
            100
          );
      }
    );

  observer.observe(
    document.body,
    {
      childList: true,
      subtree: true
    }
  );
}


/**
 * ============================================================
 * start
 * ============================================================
 *
 * Reference Engineを開始する。
 *
 * ページ表示を優先し、
 * 最初に現在存在するDOMを処理する。
 *
 * その後MutationObserverで遅延DOMを監視する。
 *
 * ============================================================
 */

function start() {

  /*
   * 初回処理。
   */

  process();


  /*
   * 遅延DOM監視。
   */

  setupObserver();


  /*
   * Click処理。
   */

  setupClickHandler();
}


/**
 * ============================================================
 * DOM Ready
 * ============================================================
 */

if (
  document.readyState ===
  "loading"
) {

  document.addEventListener(
    "DOMContentLoaded",
    start
  );

} else {

  start();
}


