/* ===================================
Home / Category Page
Category List
Count All Published Posts
====================================== */

document.addEventListener("DOMContentLoaded", function () {

  const categoryList =
    document.querySelector(
      ".home-category-list"
    );

  const categoryPageList =
    document.querySelector(
      ".category-page-list"
    );

  if (!categoryList && !categoryPageList) {
    return;
  }

  /*
   * Blogger公開投稿フィードから
   * 全記事を取得してカテゴリーを集計
   */
  async function loadAllCategories() {

    const categories =
      new Map();

    let startIndex = 1;
    const maxResults = 500;

    while (true) {

      const url =
        "/feeds/posts/default" +
        "?alt=json" +
        "&max-results=" +
        maxResults +
        "&start-index=" +
        startIndex;

      const response =
        await fetch(url);

      if (!response.ok) {
        throw new Error(
          "Blogger feed error: " +
          response.status
        );
      }

      const data =
        await response.json();

      const entries =
        data.feed &&
        data.feed.entry
          ? data.feed.entry
          : [];

      if (!entries.length) {
        break;
      }

      entries.forEach(function (entry) {

        const labels =
          entry.category || [];

        labels.forEach(function (label) {

          const name =
            label.term;

          if (!name) {
            return;
          }

          if (!categories.has(name)) {
            categories.set(name, {
              count: 0
            });
          }

          categories.get(name).count++;

        });

      });

      /*
       * 取得した件数が
       * maxResults未満なら終了
       */
      if (entries.length < maxResults) {
        break;
      }

      startIndex +=
        entries.length;

    }

    return categories;
  }

  /*
   * カテゴリー一覧を作成
   */
  function createCategoryList(
    container,
    categories,
    nameClass,
    countClass
  ) {

    container.innerHTML = "";

    categories.forEach(
      function (category, name) {

        const link =
          document.createElement("a");

        link.href =
          "/search/label/" +
          encodeURIComponent(name);

        const nameSpan =
          document.createElement("span");

        nameSpan.className =
          nameClass;

        nameSpan.textContent =
          name;

        const countSpan =
          document.createElement("span");

        countSpan.className =
          countClass;

        countSpan.textContent =
          "(" + category.count + ")";

        link.appendChild(
          nameSpan
        );

        link.appendChild(
          countSpan
        );

        container.appendChild(
          link
        );

      }
    );

  }

  /*
   * カテゴリーを表示
   */
  async function renderCategories() {

    try {

      const categories =
        await loadAllCategories();

      /*
       * Home
       */
      if (categoryList) {

        createCategoryList(
          categoryList,
          categories,
          "home-category-name",
          "home-category-count"
        );

      }

      /*
       * カテゴリーページ
       */
      if (categoryPageList) {

        createCategoryList(
          categoryPageList,
          categories,
          "category-page-name",
          "category-page-count"
        );

      }

    } catch (error) {

      console.error(
        "Category loading failed:",
        error
      );

    }

  }

  renderCategories();

});

