/**
 * Header Share
 * ヘッダーの共有メニューを制御する。
 */
(function () {

  /**
   * 現在のページURLを取得する。
   */
  function getPageUrl() {
    return window.location.href;
  }

  /**
   * 現在のページタイトルを取得する。
   */
  function getPageTitle() {
    return document.title;
  }

  /**
   * 共有URLを生成する。
   */
  function buildShareUrl(type) {

    const url =
      encodeURIComponent(
        getPageUrl()
      );

    const title =
      encodeURIComponent(
        getPageTitle()
      );

    switch (type) {

      case 'x':
        return (
          'https://twitter.com/intent/tweet' +
          '?url=' + url +
          '&text=' + title
        );

      case 'facebook':
        return (
          'https://www.facebook.com/sharer/sharer.php' +
          '?u=' + url
        );

      case 'line':
        return (
          'https://social-plugins.line.me/lineit/share' +
          '?url=' + url
        );

      case 'mail':
        return (
          'mailto:?subject=' +
          title +
          '&body=' +
          encodeURIComponent(
            getPageTitle() +
            '\n\n' +
            getPageUrl()
          )
        );

      default:
        return '#';

    }
  }

  /**
   * 共有メニューを初期化する。
   */
  function setupHeaderShare() {

    const share =
      document.querySelector(
        '.header-share'
      );

    if (!share) {
      return;
    }

    const button =
      share.querySelector(
        '.header-share-button'
      );

    const menu =
      share.querySelector(
        '.header-share-menu'
      );

    if (!button || !menu) {
      return;
    }

    /*
     * 共有ボタン。
     */
    button.addEventListener(
      'click',
      function (event) {

        event.stopPropagation();

        const isOpen =
          share.classList.contains(
            'is-open'
          );

        share.classList.toggle(
          'is-open',
          !isOpen
        );

        button.setAttribute(
          'aria-expanded',
          String(!isOpen)
        );

      }
    );

    /*
     * 共有リンク。
     */
    const items =
      share.querySelectorAll(
        '[data-share]'
      );

    items.forEach(
      function (item) {

        const type =
          item.getAttribute(
            'data-share'
          );

        /*
         * リンク共有。
         */
        if (
          type === 'x' ||
          type === 'facebook' ||
          type === 'line'
        ) {

          item.href =
            buildShareUrl(type);

          return;
        }

        /*
         * メール共有。
         */
        if (type === 'mail') {

          item.href =
            buildShareUrl('mail');

          return;
        }

        /*
         * URLコピー。
         */
        if (type === 'copy') {

          item.addEventListener(
            'click',
            function () {

              const url =
                getPageUrl();

              navigator.clipboard
                .writeText(url)
                .then(
                  function () {

                    item.textContent =
                      'コピーしました';

                    setTimeout(
                      function () {

                        item.textContent =
                          'リンクをコピー';

                      },
                      1500
                    );

                  }
                )
                .catch(
                  function () {

                    window.prompt(
                      'リンクをコピーしてください',
                      url
                    );

                  }
                );

            }
          );

        }

      }
    );

    /*
     * メニュー外をクリックしたら閉じる。
     */
    document.addEventListener(
      'click',
      function () {

        share.classList.remove(
          'is-open'
        );

        button.setAttribute(
          'aria-expanded',
          'false'
        );

      }
    );

  }

  /*
   * DOM読み込み後に初期化。
   */
  if (
    document.readyState ===
    'loading'
  ) {

    document.addEventListener(
      'DOMContentLoaded',
      setupHeaderShare
    );

  } else {

    setupHeaderShare();

  }

})();

