/* ===================================
   HeaderLinkCopy JS
   現在のページURLをコピー
   =================================== */

document.addEventListener('DOMContentLoaded', function () {

  var copyButton = document.querySelector('.header-tool-copy');
  var copyStatus = document.querySelector('.header-copy-status');

  if (!copyButton || !copyStatus) {
    return;
  }

  var hideTimer = null;
  var clearTimer = null;

  function showCopied() {

    if (hideTimer) {
      clearTimeout(hideTimer);
    }

    if (clearTimer) {
      clearTimeout(clearTimer);
    }

    copyStatus.textContent = 'コピーしました';
    copyStatus.style.visibility = 'visible';
    copyStatus.style.opacity = '1';

    hideTimer = setTimeout(function () {

      copyStatus.style.opacity = '0';
      clearTimer = setTimeout(function () {
        copyStatus.style.visibility = 'hidden';
        copyStatus.textContent = '';
      }, 250);

    }, 1500);
  }

  function showCopyError() {

    if (hideTimer) {
      clearTimeout(hideTimer);
    }

    if (clearTimer) {
      clearTimeout(clearTimer);
    }

    copyStatus.textContent = 'コピーできませんでした';
    copyStatus.style.opacity = '1';

    hideTimer = setTimeout(function () {

      copyStatus.style.opacity = '0';
      clearTimer = setTimeout(function () {
        copyStatus.style.visibility = 'hidden';
        copyStatus.textContent = '';
      }, 250);

    }, 1500);
  }

  function fallbackCopy(url) {

    var textarea = document.createElement('textarea');

    textarea.value = url;
    textarea.setAttribute('readonly', '');
    textarea.style.position = 'fixed';
    textarea.style.left = '-9999px';

    document.body.appendChild(textarea);
    textarea.select();

    try {
      document.execCommand('copy');
      showCopied();
    } catch (error) {
      showCopyError();
    }

    document.body.removeChild(textarea);
  }

  copyButton.addEventListener('click', function () {

    var url = window.location.href;

    if (navigator.clipboard && window.isSecureContext) {

      navigator.clipboard.writeText(url)
        .then(function () {
          showCopied();
        })
        .catch(function () {
          fallbackCopy(url);
        });

    } else {

      fallbackCopy(url);

    }

  });

});

